//name: TTS自动循环v2
//author: Custom
//description: TTS朗读 + 自动发送 + 文本过滤 + 文本重发
(function() {
    "use strict";

    var BTN_NAME = '设置';
    var BTN_READ = '阅读';
    var PANEL_ID = 'ta-panel';
    var PANEL_OVERLAY_ID = 'ta-panel-overlay';
    var STYLE_ID = 'ta-styles';
    var SETTINGS_KEY = 'ta_assistant_v2';
    var BAGU_HISTORY_KEY = 'ta_assistant_v2_bagu_history';

    var BAGU_DEFAULT_PROMPT = [
        '你是中文小说口吻修订员。只修正待朗读正文中的模板化“八股腔”，不改变事件、人物意图、视角、称呼、时态和信息量。',
        '',
        '重点修正：',
        '1. 反复的否定定义：“不是X，而是Y”、“不是X，是Y”，改为直接的肯定叙述或感官细节。',
        '2. 空泛、滥用或无场景锚点的比喻，尤其“像XXX一样”、“仿佛”、“宛如”、“好像”；能直写就直写，有效且新鲜的场景比喻可保留。',
        '3. 解释人物意图、替读者总结效果、抽象情绪堆叠；优先用动作、对话节奏和当前场景细节呈现。',
        '4. 陈词滥调的身体反应、精密仪器/机械化描写、不必要的精确数字和句式重复。',
        '5. 修正后必须自然、连贯、适合有声朗读；对白的人物风格不得被抹平。',
        '',
        '只输出一个 JSON 数组，不要解释、不要 Markdown：',
        '[{"original":"需修正的原文片段（必须逐字准确）","corrected":"修正后文本"}]',
        '只列出需修正的片段；无需修正时输出 []。corrected 为空字符串表示删除。'
    ].join('\n');

    var DEFAULTS = {
        running: false,
        autoRead: false,
        autoSend: { enabled: true, text: '继续', maxRounds: 0, optionMode: 'fixed', optionIndex: 1, bootstrapLast: true, dreamCountMode: 'one', dreamResolveConflicts: true },
        tts: { enabled: true, voice: 'female_1', rate: 0 },
        bagu: { enabled: false, rewriteChat: true, skipFloorZero: true, minLength: 50, timeoutMs: 180000, apiUrl: '', apiKey: '', model: '', apiSource: 'auto', extractStart: '', extractEnd: '', prompt: BAGU_DEFAULT_PROMPT },
        bgm: { enabled: false, bilibiliUrl: '', controlMode: 'message', showPlayer: true, continueAfterStop: false, autoNextPart: true, loopParts: true, backgroundKeepAliveV1: true },
        textFilter: { enabled: false, readEnabled: false, readRanges: [], skipEnabled: false, skipRanges: [] },
        regexFilter: { enabled: false, disabledIds: [] },
        textResend: { enabled: false, requiredTags: [], maxRetries: 3, retryDelay: 500 }
    };

    var EDGE_VOICES = [
        { key: 'female_1', name: '晓晓', tag: '温暖百变女声' },
        { key: 'male_1', name: '云希', tag: '少年温暖男声' },
        { key: 'female_2', name: '晓伊', tag: '女声' },
        { key: 'male_2', name: '云健', tag: '男声' },
        { key: 'female_3', name: '晓梦', tag: '女声' },
        { key: 'male_3', name: '云扬', tag: '男声' },
        { key: 'female_4', name: '晓涵', tag: '女声' },
        { key: 'male_4', name: '云峰', tag: '男声' },
        { key: 'hk_female_1', name: '晓佳(粤)', tag: '粤语女声' },
        { key: 'hk_female_2', name: '晓曼(粤)', tag: '粤语女声' },
        { key: 'hk_male_1', name: '云龙(粤)', tag: '粤语男声' },
        { key: 'tw_female_1', name: '晓臻(台)', tag: '台语女声' },
        { key: 'tw_female_2', name: '晓雨(台)', tag: '台语女声' },
        { key: 'tw_male_1', name: '云哲(台)', tag: '台语男声' },
        { key: 'en_female_1', name: 'Aria(EN)', tag: '英文女声' },
        { key: 'en_female_2', name: 'Jenny(EN)', tag: '英文女声' },
        { key: 'en_female_3', name: 'Ana(EN)', tag: '英文女声' },
        { key: 'en_male_1', name: 'Guy(EN)', tag: '英文男声' },
        { key: 'en_male_2', name: 'Eric(EN)', tag: '英文男声' },
        { key: 'ja_female_1', name: 'Nanami(JP)', tag: '日文女声' },
        { key: 'ja_male_1', name: 'Keita(JP)', tag: '日文男声' }
    ];

    // ============ 日志系统 ============
    var logBuf = [];
    function addLog(level, msg) {
        var entry = { t: new Date().toLocaleTimeString(), l: level, m: msg };
        logBuf.push(entry);
        if (logBuf.length > 500) logBuf.shift();
        var prefix = '[TTS助手][' + level + ']';
        console.log(prefix + ' ' + msg);
        if (level === 'error' || level === 'warn') {
            if (!panelOpen || currentTab !== 'log') unreadLogAlerts = (unreadLogAlerts || 0) + 1;
            var toastMethod = level === 'error' ? 'error' : 'warning';
            window.toastr && window.toastr[toastMethod] && window.toastr[toastMethod](msg, 'TTS自动循环');
        }
    }

    // ============ 设置 ============
    var settings = {};
    function loadSettings() {
        try {
            var raw = localStorage.getItem(SETTINGS_KEY);
            var parsed = raw ? JSON.parse(raw) : null;
            settings = parsed ? $.extend(true, {}, DEFAULTS, parsed) : $.extend(true, {}, DEFAULTS);
            // DeepSeek V4 Flash 会把输出额度的一部分用于内置推理；旧版90秒配置容易在正文返回前中断。
            if (parsed && settings.bagu && isSlowReasoningBaguModel(settings.bagu) && (settings.bagu.timeoutMs || 0) < 180000) {
                settings.bagu.timeoutMs = 180000;
                localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings));
            }
            // 旧版强制模式会在后台重建有声iframe，容易被浏览器拦截到页面重新获得焦点。
            if (parsed && parsed.bgm && !parsed.bgm.backgroundKeepAliveV1) {
                settings.bgm.controlMode = 'message';
                settings.bgm.backgroundKeepAliveV1 = true;
                localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings));
            }
        } catch (e) { settings = $.extend(true, {}, DEFAULTS); }
    }
    function saveSettings() {
        try { localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings)); } catch (e) {}
    }

                // ============ TTS ============
    var TTS_URL = 'https://edgetts.velure.codes/';

    async function ttsSingle(text, voice, rate, signal) {
        var speed = 1.0 + (rate || 0) / 100;
        if (speed < 0.5) speed = 0.5;
        if (speed > 2.0) speed = 2.0;
        var r = await window.parent.fetch(TTS_URL, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            signal: signal,
            body: JSON.stringify({ voiceKey: voice, text: text, speed: speed, uid: 'ta_' + Date.now(), reqid: 'ta-' + Date.now() })
        });
        if (!r.ok) throw new Error('HTTP ' + r.status);
        var data = await r.json();
        if (!data.data) throw new Error('无音频数据');
        var raw = atob(data.data);
        var bytes = new Uint8Array(raw.length);
        for (var i = 0; i < raw.length; i++) bytes[i] = raw.charCodeAt(i);
        return new Blob([bytes], { type: 'audio/mpeg' });
    }


    async function synTTS(text, voice, rate, signal) {
        if (text.length <= 3000) return await ttsSingle(text, voice, rate, signal);
        var parts = text.match(/[^。！？!?.\n]+[。！？!?.\n]?/g) || [text];
        var chunks = [], cur = '';
        for (var i = 0; i < parts.length; i++) {
            if (cur.length + parts[i].length > 3000 && cur) { chunks.push(cur.trim()); cur = ''; }
            cur += parts[i];
        }
        if (cur.trim()) chunks.push(cur.trim());
        var blobs = [];
        for (var j = 0; j < chunks.length; j++) {
            if (signal && signal.aborted) throw new DOMException('已取消', 'AbortError');
            blobs.push(await ttsSingle(chunks[j], voice, rate, signal));
        }
        return new Blob(blobs, { type: 'audio/mpeg' });
    }

    // ============ IndexedDB 缓存 ============
    var DB = null;
    function openDB() {
        if (DB) return Promise.resolve(DB);
        return new Promise(function(resolve) {
            var req = indexedDB.open('ta-tts', 1);
            req.onupgradeneeded = function(e) { e.target.result.createObjectStore('tts', { keyPath: 'k' }); };
            req.onsuccess = function(e) { DB = e.target.result; resolve(DB); };
            req.onerror = function() { resolve(null); };
        });
    }
    function textFingerprint(text) {
        var h1 = 2166136261, h2 = 5381, s = String(text || '');
        for (var i = 0; i < s.length; i++) {
            var c = s.charCodeAt(i);
            h1 ^= c; h1 = Math.imul(h1, 16777619);
            h2 = Math.imul(h2, 33) ^ c;
        }
        return (h1 >>> 0).toString(36) + ':' + (h2 >>> 0).toString(36) + ':' + s.length;
    }
    function cKey(text, voice, rate) {
        return 'tts:v2:' + textFingerprint(voice + '|' + (rate || 0) + '|' + text);
    }
    async function getCached(key) {
        try {
            var db = await openDB();
            if (!db) return null;
            return new Promise(function(resolve) {
                var req = db.transaction('tts', 'readonly').objectStore('tts').get(key);
                req.onsuccess = function() {
                    var e = req.result;
                    if (e && Date.now() - e.t < 604800000) { resolve(e.b); return; }
                    if (e) {
                        try { db.transaction('tts', 'readwrite').objectStore('tts').delete(key); } catch (x) {}
                    }
                    resolve(null);
                };
                req.onerror = function() { resolve(null); };
            });
        } catch (e) { return null; }
    }
    async function setCached(key, blob) {
        try {
            var db = await openDB();
            if (!db) return;
            return new Promise(function(resolve) {
                var tx = db.transaction('tts', 'readwrite');
                tx.objectStore('tts').put({ k: key, b: blob, t: Date.now() });
                tx.oncomplete = resolve; tx.onerror = resolve;
            });
        } catch (e) {}
    }
    async function cleanupCache() {
        try {
            var db = await openDB();
            if (!db) return;
            var tx = db.transaction('tts', 'readwrite'), store = tx.objectStore('tts');
            var req = store.openCursor(), live = [];
            req.onsuccess = function() {
                var cur = req.result;
                if (!cur) {
                    live.sort(function(a, b) { return b.t - a.t; });
                    for (var i = 200; i < live.length; i++) store.delete(live[i].k);
                    return;
                }
                var value = cur.value || {};
                if (!value.t || Date.now() - value.t >= 604800000) cur.delete();
                else live.push({ k: value.k, t: value.t });
                cur.continue();
            };
        } catch (e) {}
    }

    // ============ 播放器 ============
    function AudioQ(onStart, onFailure, onIdle) {
        this.q = []; this.cur = null; this.a = null; this.url = null; this.p = false; this.seq = 0;
        this._s = onStart || null; this._e = onFailure || null; this._i = onIdle || null;
    }
    AudioQ.prototype.enqueue = function(item) {
        if (!item || !item.blob) return false;
        for (var i = 0; i < this.q.length; i++) if (this.q[i].id === item.id) return false;
        if (this.cur && this.cur.id === item.id) return false;
        this.q.push(item);
        if (!this.p) this._next();
        return true;
    };
    AudioQ.prototype.clear = function() { this.q = []; this._stop(); this.cur = null; this.p = false; };
    AudioQ.prototype._next = function() {
        if (!this.q.length) { this.p = false; this.cur = null; hideNowPlaying(); if (this._i) this._i(); return; }
        this._play(this.q.shift());
    };
    AudioQ.prototype._play = function(item) {
        this.p = true; this.cur = item;
        showNowPlaying(item);
        var url = URL.createObjectURL(item.blob), a = new Audio(url), self = this, cleaned = false, started = false;
        var seq = ++this.seq;
        this.a = a; this.url = url;
        var done = function() {
            if (cleaned) return;
            cleaned = true;
            a.onplaying = a.onended = a.onerror = null;
            try { URL.revokeObjectURL(url); } catch (e) {}
            if (self.a === a) self.a = null;
            if (self.url === url) self.url = null;
        };
        a.onplaying = function() {
            if (started || self.seq !== seq) return;
            started = true;
            if (self._s) self._s(item, a);
        };
        a.onended = function() { if (self.seq !== seq) return; done(); self._next(); };
        a.onerror = function() { if (self.seq !== seq) return; if (self._e) self._e(item); done(); self._next(); };
        a.play().catch(function() { if (self.seq !== seq) return; if (self._e) self._e(item); done(); self._next(); });
    };
    AudioQ.prototype._stop = function() {
        this.seq++;
        var a = this.a, url = this.url;
        if (a) {
            a.onplaying = a.onended = a.onerror = null;
            try { a.pause(); a.removeAttribute('src'); a.load(); } catch (e) {}
        }
        if (url) { try { URL.revokeObjectURL(url); } catch (e) {} }
        this.a = null; this.url = null;
        hideNowPlaying();
    };

    // ============ B站背景音乐 ============
    var BILI_HOST_ID = 'ta-bili-bgm-host';
    var bgm = null;

    function parseBilibiliUrl(input) {
        var raw = String(input || '').trim(), m, info = null;
        m = raw.match(/(BV[0-9A-Za-z]{10})/i);
        if (m) info = { type: 'bvid', id: m[1] };
        if (!info) {
            m = raw.match(/(?:^|\/)av(\d+)/i) || raw.match(/[?&]aid=(\d+)/i) || raw.match(/^(\d+)$/);
            if (m) info = { type: 'aid', id: m[1] };
        }
        if (!info) return null;
        m = raw.match(/[?&]p=(\d+)/i);
        info.page = m ? Math.max(1, parseInt(m[1], 10) || 1) : 1;
        return info;
    }

    function BiliBGM() {
        this.host = null; this.frame = null; this.status = '未加载';
        this.active = false; this.pausedForTTS = false; this.stopAfterIdle = false;
        this.position = 0; this.startedAt = 0; this.info = null; this.source = '';
        this.pages = []; this.metaToken = 0; this.partWatch = null; this.partSwitching = false;
        this.bindPlayerMessages();
    }
    BiliBGM.prototype.bindPlayerMessages = function() {
        var owner = window.parent, self = this;
        if (owner._ta_bili_message_handler) {
            try { owner.removeEventListener('message', owner._ta_bili_message_handler); } catch (e) {}
        }
        owner._ta_bili_message_handler = function(event) {
            if (!self.frame || event.source !== self.frame.contentWindow) return;
            if (event.origin && !/https?:\/\/(?:player\.|www\.)?bilibili\.com$/i.test(event.origin)) return;
            var data = event.data, type = '';
            if (typeof data === 'string') {
                if (data === 'bilibili:player:ended') type = 'ended';
                else {
                    var raw = data.replace(/^playerOperation-/, '');
                    try { data = JSON.parse(raw); } catch (e) { type = raw; }
                }
            }
            if (!type && data && typeof data === 'object') {
                type = data.type || data.event || data.command || data.key || data.state || '';
                if (!type && data.data && typeof data.data === 'object') type = data.data.type || data.data.event || '';
            }
            type = String(type || '').toLowerCase();
            if (/(?:^|[_:-])playing(?:$|[_:-])/.test(type)) {
                if (self.active && !self.pausedForTTS) {
                    if (!self.startedAt) self.startedAt = Date.now();
                    self.startPartWatch();
                }
            } else if (/(?:^|[_:-])(?:ended|finished|complete|completed)(?:$|[_:-])/.test(type)) {
                self.advancePart('播放器结束事件');
            }
        };
        owner.addEventListener('message', owner._ta_bili_message_handler);
        if (owner._ta_bili_visibility_handler) {
            try { PD().removeEventListener('visibilitychange', owner._ta_bili_visibility_handler); } catch (e) {}
        }
        owner._ta_bili_visibility_handler = function() { if (!PD().hidden) self.checkPartEnd(); };
        PD().addEventListener('visibilitychange', owner._ta_bili_visibility_handler);
    };
    BiliBGM.prototype.currentPageMeta = function() {
        if (!this.info || !this.pages.length) return null;
        for (var i = 0; i < this.pages.length; i++) if (Number(this.pages[i].page) === Number(this.info.page)) return this.pages[i];
        return null;
    };
    BiliBGM.prototype.currentElapsed = function() {
        return this.position + (this.startedAt ? Math.max(0, (Date.now() - this.startedAt) / 1000) : 0);
    };
    BiliBGM.prototype.clearPartWatch = function() {
        if (this.partWatch) clearInterval(this.partWatch);
        this.partWatch = null;
    };
    BiliBGM.prototype.startPartWatch = function() {
        this.clearPartWatch();
        var page = this.currentPageMeta(), self = this;
        if (!settings.bgm.autoNextPart || !this.active || this.pausedForTTS || !page || !page.duration) return;
        this.partWatch = setInterval(function() { self.checkPartEnd(); }, 1500);
    };
    BiliBGM.prototype.checkPartEnd = function() {
        var page = this.currentPageMeta();
        if (!settings.bgm.autoNextPart || !this.active || this.pausedForTTS || !page || !page.duration) return;
        // 给iframe加载、缓冲和片尾状态留出少量余量；结束消息若可用会更早触发。
        if (this.currentElapsed() >= Number(page.duration) + 4) this.advancePart('分P时长兜底');
    };
    BiliBGM.prototype.partStatus = function(prefix) {
        var page = this.currentPageMeta();
        if (!this.info) return prefix || '未加载';
        if (!page) return (prefix || '播放中') + ' · ' + this.info.id + ' P' + this.info.page;
        return (prefix || '播放中') + ' · ' + this.info.id + ' · P' + page.page + '/' + this.pages.length + (page.part ? ' ' + page.part : '');
    };
    BiliBGM.prototype.advancePart = function(reason) {
        if (this.partSwitching || !settings.bgm.autoNextPart || !this.active || this.pausedForTTS || !this.pages.length || !this.info) return false;
        var index = -1;
        for (var i = 0; i < this.pages.length; i++) if (Number(this.pages[i].page) === Number(this.info.page)) { index = i; break; }
        if (index < 0) index = 0;
        var nextIndex = index + 1;
        if (nextIndex >= this.pages.length) {
            if (settings.bgm.loopParts === false) {
                this.pauseManual(false);
                this.setStatus('全部分P播放完成 · 已暂停');
                return false;
            }
            nextIndex = 0;
        }
        var next = this.pages[nextIndex];
        this.partSwitching = true;
        this.clearPartWatch();
        this.position = 0; this.startedAt = 0; this.info.page = next.page;
        this.active = true; this.pausedForTTS = false; this.stopAfterIdle = false;
        this.createFrame(0);
        this.setStatus(this.partStatus('自动续播'));
        addLog('info', '背景音乐' + (reason ? '（' + reason + '）' : '') + '：切换到 P' + next.page + '/' + this.pages.length + (next.part ? ' · ' + next.part : ''));
        var self = this;
        setTimeout(function() { self.partSwitching = false; }, 1800);
        return true;
    };
    BiliBGM.prototype.setStatus = function(text) {
        this.status = text;
        var el = PD().getElementById('ta-bili-bgm-status');
        if (el) el.textContent = text;
    };
    function fetchBiliJsonp(url) {
        return new Promise(function(resolve, reject) {
            var owner = window.parent, doc = PD(), callback = '__ta_bili_jsonp_' + Date.now() + '_' + Math.floor(Math.random() * 100000);
            var script = doc.createElement('script'), timer = null, done = false;
            function cleanup() {
                if (done) return;
                done = true;
                if (timer) clearTimeout(timer);
                try { delete owner[callback]; } catch (e) { owner[callback] = undefined; }
                try { script.remove(); } catch (e) {}
            }
            owner[callback] = function(data) { cleanup(); resolve(data); };
            script.onerror = function() { cleanup(); reject(new Error('JSONP请求失败')); };
            script.src = url + (url.indexOf('?') === -1 ? '?' : '&') + 'jsonp=jsonp&callback=' + encodeURIComponent(callback);
            timer = setTimeout(function() { cleanup(); reject(new Error('JSONP请求超时')); }, 12000);
            (doc.head || doc.documentElement).appendChild(script);
        });
    }
    BiliBGM.prototype.loadPartMetadata = function(info) {
        var self = this, token = ++this.metaToken;
        this.pages = []; this.clearPartWatch();
        if (!info) return;
        var query = info.type === 'bvid' ? 'bvid=' + encodeURIComponent(info.id) : 'aid=' + encodeURIComponent(info.id);
        var url = 'https://api.bilibili.com/x/web-interface/view?' + query;
        var fetchFn = window.parent && typeof window.parent.fetch === 'function' ? window.parent.fetch.bind(window.parent) : fetch;
        Promise.resolve().then(async function() {
            var data;
            try {
                var response = await fetchFn(url, { method: 'GET' });
                if (!response.ok) throw new Error('HTTP ' + response.status);
                data = await response.json();
            } catch (fetchError) {
                data = await fetchBiliJsonp(url);
            }
            if (token !== self.metaToken || !self.info || self.info.id !== info.id) return;
            if (!data || data.code !== 0 || !data.data || !Array.isArray(data.data.pages)) throw new Error(data && data.message || '分P列表为空');
            self.pages = data.data.pages.map(function(page) {
                return { page: Number(page.page) || 1, duration: Number(page.duration) || 0, part: String(page.part || ''), cid: page.cid };
            }).sort(function(a, b) { return a.page - b.page; });
            var found = false;
            for (var i = 0; i < self.pages.length; i++) if (self.pages[i].page === Number(self.info.page)) { found = true; break; }
            if (!found && self.pages.length) self.info.page = self.pages[0].page;
            addLog('info', '背景音乐已读取 ' + self.pages.length + ' 个分P，从P' + self.info.page + '开始' + (settings.bgm.loopParts !== false ? '，播完循环到P1' : ''));
            if (self.active && !self.pausedForTTS) {
                self.setStatus(self.partStatus('播放中'));
                self.startPartWatch();
            }
        }).catch(function(error) {
            if (token !== self.metaToken) return;
            self.pages = []; self.clearPartWatch();
            addLog('info', '背景音乐分P信息获取失败，继续使用单P模式: ' + (error.message || error));
            if (self.active) self.setStatus('播放中 · ' + info.id + ' P' + info.page + ' · 单P模式');
        });
    };
    BiliBGM.prototype.ensureHost = function() {
        var self = this;
