    }
    function findSecs(text, ranges) {
        var secs = [];
        for (var r = 0; r < ranges.length; r++) {
            var st = (ranges[r].start || '').trim(), et = (ranges[r].end || '').trim();
            if (!st && !et) continue;
            var sp = 0;
            while (sp < text.length) {
                var ss = st ? text.indexOf(st, sp) : 0;
                if (ss === -1) break;
                sp = st ? ss + st.length : ss + 1;
                var se = et ? text.indexOf(et, sp) : text.length;
                if (se === -1) se = text.length; else se += et.length;
                if (se <= ss) { sp = Math.max(sp, se); if (!st) break; continue; }
                secs.push({ s: ss, e: se });
                if (!st) break;
                sp = se;
            }
        }
        return secs;
    }
    function mergeSecs(secs) {
        if (!secs.length) return [];
        secs.sort(function(a, b) { return a.s - b.s; });
        var m = [];
        for (var i = 0; i < secs.length; i++) {
            if (m.length && m[m.length - 1].e >= secs[i].s) m[m.length - 1].e = Math.max(m[m.length - 1].e, secs[i].e);
            else m.push({ s: secs[i].s, e: secs[i].e });
        }
        return m;
    }
    function applyRead(text, ranges) {
        if (!ranges.length) return text;
        var secs = mergeSecs(findSecs(text, ranges));
        if (!secs.length || (secs.length === 1 && secs[0].s === 0 && secs[0].e === text.length)) return text;
        var r = '';
        for (var i = 0; i < secs.length; i++) r += text.slice(secs[i].s, secs[i].e);
        return r;
    }
    function applySkip(text, ranges) {
        if (!ranges.length) return text;
        var secs = mergeSecs(findSecs(text, ranges));
        if (!secs.length) return text;
        var r = '', p = 0;
        for (var i = 0; i < secs.length; i++) { if (secs[i].s > p) r += text.slice(p, secs[i].s); p = secs[i].e; }
        if (p < text.length) r += text.slice(p);
        return r;
    }
    function filterText(text, cfg, skipStrip) {
        if (!text) return '';
        var r = text;
        if (cfg.skipOn && cfg.skip.length) r = applySkip(r, cfg.skip);
        if (cfg.readOn && cfg.read.length) r = applyRead(r, cfg.read);
        if (skipStrip) return r;
        r = stripHtml(r);
        return r.trim();
    }

    function parseRegex(str) {
        try { return window.TavernHelper && window.TavernHelper.builtin ? window.TavernHelper.builtin.parseRegexFromString(str) : null; } catch (e) { return null; }
    }

    function syncRegexes() {
        try {
            var TH = window.TavernHelper;
            if (!TH || !TH.getTavernRegexes) { addLog('warn', '正则同步: TavernHelper 不可用'); return; }
            var gList = TH.getTavernRegexes({ type: 'global' }) || [];
            var cList = [], pList = [];
            try {
                if (!TH.isCharacterTavernRegexesEnabled || TH.isCharacterTavernRegexesEnabled()) cList = TH.getTavernRegexes({ type: 'character', name: 'current' }) || [];
            } catch (e) {}
            try { pList = TH.getTavernRegexes({ type: 'preset', name: 'in_use' }) || []; } catch (e) {}
            syncedRegexes = gList.concat(cList, pList);
            addLog('info', '正则同步: 获取到 ' + syncedRegexes.length + ' 条正则');
        } catch (e) { addLog('error', '正则同步失败: ' + e.message); }
    }

    function parseDreamQuestions(text) {
        if (!text) return [];
        try {
            var box = PD().createElement('div');
            box.innerHTML = String(text);
            var roots = box.querySelectorAll('dream_big_discuss');
            if (!roots.length) return [];
            var root = roots[roots.length - 1], nodes = root.querySelectorAll('q'), result = [], invalid = 0;
            for (var i = 0; i < nodes.length; i++) {
                var question = (nodes[i].getAttribute('content') || '').trim(), answers = [];
                var children = nodes[i].children || [];
                for (var j = 0; j < children.length; j++) {
                    if (String(children[j].tagName || '').toLowerCase() !== 'a') continue;
                    var answer = (children[j].textContent || '').trim();
                    if (answer && answers.indexOf(answer) === -1) answers.push(answer);
                }
                if (question && answers.length) result.push({ question: question, answers: answers });
                else invalid++;
            }
            if (invalid) addLog('warn', '梦境共创: 跳过 ' + invalid + ' 个缺少问题或答案的无效节点');
            return result;
        } catch (e) {
            addLog('warn', '梦境共创解析失败，将使用发送文本: ' + e.message);
            return [];
        }
    }

    function escapeDreamAttribute(text) {
        return String(text || '').replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    }

    function escapeDreamText(text) {
        return String(text || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    }

    function selectDreamQuestions(questions, countMode) {
        var indexed = questions.map(function(q, i) { return { q: q, index: i }; });
        var count = indexed.length;
        if (countMode === 'one') count = Math.min(1, indexed.length);
        else if (countMode === 'random') count = indexed.length ? 1 + Math.floor(Math.random() * indexed.length) : 0;
        for (var i = indexed.length - 1; i > 0; i--) {
            var j = Math.floor(Math.random() * (i + 1)), tmp = indexed[i];
            indexed[i] = indexed[j]; indexed[j] = tmp;
        }
        return indexed.slice(0, count).sort(function(a, b) { return a.index - b.index; }).map(function(x) { return x.q; });
    }

    function buildDreamAnswer(questions, countMode, resolveConflicts) {
        var selected = selectDreamQuestions(questions, countMode || 'one'), blocks = [];
        for (var i = 0; i < selected.length; i++) {
            var q = selected[i], answer = q.answers[Math.floor(Math.random() * q.answers.length)];
            blocks.push('<dream_answer q="' + escapeDreamAttribute(q.question) + '">\n' + escapeDreamText(answer) + '\n</dream_answer>');
            addLog('send', '梦境共创 #' + (i + 1) + ': ' + answer.slice(0, 80) + (answer.length > 80 ? '…' : ''));
        }
        var text = blocks.join('\n\n');
        if (selected.length > 1 && resolveConflicts) {
            text += '\n\n如果以上回答之间存在冲突，请结合当前剧情自行判断，并自动选择最合理的剧情走向。';
        }
        return { text: text, count: selected.length, total: questions.length };
    }

    function applyRegexes(text) {
        var TH = window.TavernHelper;
        var disabled = settings.regexFilter.disabledIds || [];
        if (!disabled.length && TH && TH.formatAsTavernRegexedString) {
            try {
                var formatted = TH.formatAsTavernRegexedString(text, 'ai_output', 'display', { depth: 0 });
                if (typeof formatted === 'string') return formatted;
            } catch (e) { addLog('warn', '官方正则格式化失败，改用同步列表: ' + e.message); }
        }
        if (!syncedRegexes || !syncedRegexes.length) return text;
        var r = text;
        for (var i = 0; i < syncedRegexes.length; i++) {
            var rx = syncedRegexes[i];
            if (!rx.enabled || !rx.source || !rx.source.ai_output) continue;
            if (!rx.destination || !rx.destination.display) continue;
            if (rx.min_depth !== null && rx.min_depth !== undefined && 0 < rx.min_depth) continue;
            if (rx.max_depth !== null && rx.max_depth !== undefined && 0 > rx.max_depth) continue;
            if (disabled.indexOf(rx.id) !== -1) continue;
            var re = parseRegex(rx.find_regex);
            if (!re) continue;
            try { r = r.replace(re, rx.replace_string || ''); } catch (e) {}
        }
        return r;
    }

    // ============ 状态 ============
    var lastSentId = null, isResending = false, procIds = {}, player = null, isRangeReading = false;
    var panelOpen = false, currentTab = 'home', roundCount = 0;
    var lastOptions = null, lastDreamQuestions = null, regenMid = null;
    var syncedRegexes = null;
    var cyclePaused = false, cycleCompleted = false, pendingAdvanceId = null;
    var rangeReadToken = 0, rangeProgressText = '';
    var activeSession = 0, ttsControllers = [], messageWaiters = [], baguGenerationIds = [];
    var baguStatusJobs = {}, baguStatusTimer = null, baguCheckedVersions = {}, manualBaguRunning = false;
    var homeMode = 'cycle', uiPreview = { filter: null, bagu: null }, logFilter = 'all', unreadLogAlerts = 0;
