    function untrackController(controller) { ttsControllers = ttsControllers.filter(function(x) { return x !== controller; }); }
    function waitForAssistantMessage(token, timeoutMs) {
        return new Promise(function(resolve) {
            var finished = false, listener = null, timer = null;
            var finish = function(value) {
                if (finished) return;
                finished = true;
                if (timer) clearTimeout(timer);
                if (listener && listener.stop) listener.stop();
                messageWaiters = messageWaiters.filter(function(x) { return x !== cancel; });
                resolve(value || null);
            };
            var cancel = function() { finish(null); };
            messageWaiters.push(cancel);
            listener = window.eventOn(window.tavern_events.MESSAGE_RECEIVED, function(messageId) {
                if (token !== activeSession) { finish(null); return; }
                setTimeout(function() {
                    try {
                        var list = window.TavernHelper.getChatMessages(messageId, { role: 'assistant' }) || [];
                        if (list[0] && list[0].message) finish(list[0]);
                    } catch (e) {}
