            });
            timer = setTimeout(function() { finish(null); }, timeoutMs || 35000);
        });
    }

    function resetState() {
        lastSentId = null; isResending = false; procIds = {}; roundCount = 0;
        lastOptions = null; lastDreamQuestions = null; regenMid = null; pendingAdvanceId = null; cycleCompleted = false;
