        var id = String(mid).indexOf('msg-') === 0 ? String(mid) : 'msg-' + mid;
        if (lastSentId === id) return;
        if (cyclePaused) {
            pendingAdvanceId = id;
            addLog('info', (reason || '本轮处理完毕') + '，已暂停等待继续');
            refreshPanel();
            return;
