    // ============ 自动发送 ============
    async function doAutoSend() {
        if (!settings.running || isResending || !settings.autoSend.enabled) return;
        var maxR = settings.autoSend.maxRounds || 0;
        if (maxR > 0 && roundCount >= maxR) {
            completeCycle('已完成 ' + maxR + ' 轮，最后一条语音继续播放');
            return;
        }
        if (sendInFlightToken === activeSession) { sendQueued = true; return; }
        var token = activeSession;
        sendInFlightToken = token;
        roundCount++;
        renderTaskStatus();
        var mode = settings.autoSend.optionMode || 'fixed';
        var text = settings.autoSend.text || '继续';
        if (mode === 'dream' && lastDreamQuestions && lastDreamQuestions.length) {
            var dreamPayload = buildDreamAnswer(lastDreamQuestions, settings.autoSend.dreamCountMode || 'one', settings.autoSend.dreamResolveConflicts !== false);
            text = dreamPayload.text;
            addLog('send', '自动发送[' + roundCount + (maxR > 0 ? '/' + maxR : '') + '] 梦境共创: 已回答 ' + dreamPayload.count + '/' + dreamPayload.total + ' 个问题');
        } else if (mode === 'dream') {
            addLog('warn', '自动发送[' + roundCount + (maxR > 0 ? '/' + maxR : '') + '] 未找到有效梦境选项，回退发送文本且继续循环: ' + text);
        } else if (mode === 'random' && lastOptions && lastOptions.length) {
            text = lastOptions[Math.floor(Math.random() * lastOptions.length)];
            addLog('send', '自动发送[' + roundCount + (maxR > 0 ? '/' + maxR : '') + '] 随机: ' + text);
        } else if (mode === 'pick' && lastOptions && lastOptions.length) {
            var idx = Math.max(0, Math.min((settings.autoSend.optionIndex || 1) - 1, lastOptions.length - 1));
            text = lastOptions[idx];
            addLog('send', '自动发送[' + roundCount + (maxR > 0 ? '/' + maxR : '') + '] 选项#' + (idx + 1) + ': ' + text);
        } else if (mode !== 'fixed' && (!lastOptions || !lastOptions.length)) {
