    // ============ 文本重发 ============
    async function ensureTags(text, messageId, token) {
        if (!settings.textResend.enabled || !settings.textResend.requiredTags.length) return { ok: true, text: text, messageId: messageId };
        var tags = settings.textResend.requiredTags, maxR = settings.textResend.maxRetries, delMs = settings.textResend.retryDelay;
        var cur = text, targetId = messageId;
        for (var at = 0; at <= maxR; at++) {
            var miss = [];
            for (var t = 0; t < tags.length; t++) if (cur.indexOf(tags[t]) === -1) miss.push(tags[t]);
            if (!miss.length) return { ok: true, text: cur, messageId: targetId };
            if (at >= maxR) {
                addLog('warn', '重发达上限(' + maxR + '次)，跳过标签检查');
                return { ok: true, text: cur, messageId: targetId };
            }
            addLog('warn', '缺少标签 ' + miss.join(', ') + '，重试(' + (at + 1) + '/' + maxR + ')');
            if (!settings.textResend.enabled || token !== activeSession) { addLog('warn', '重发被停止中断'); isResending = false; return { ok: false, text: cur, messageId: targetId }; }
            isResending = true;
            try {
                await dly(delMs);
                if (token !== activeSession) return { ok: false, text: cur, messageId: targetId };
                var TH = window.TavernHelper;
                var current = TH.getChatMessages(targetId, { role: 'assistant' }) || [];
                if (!current[0]) throw new Error('目标消息 #' + targetId + ' 已不存在，取消重发');
                if (textFingerprint(current[0].message) !== textFingerprint(cur)) throw new Error('目标消息 #' + targetId + ' 已被修改，取消重发');
                var waiter = waitForAssistantMessage(token, 35000);
                await TH.deleteChatMessages([targetId]);
                if (token !== activeSession) return { ok: false, text: cur, messageId: targetId };
                await TH.triggerSlash('/trigger');
                var regenerated = await waiter;
                if (regenerated) {
                    cur = regenerated.message;
                    targetId = regenerated.message_id;
                    regenMid = targetId;
                    addLog('info', '重试' + (at + 1) + ': 获取到新消息 #' + targetId);
                } else {
                    addLog('warn', '重试' + (at + 1) + ': 等待消息超时，终止本轮');
                    return { ok: false, text: cur, messageId: targetId };
                }
            } catch (e) {
                if (token === activeSession) cancelMessageWaiters();
                addLog('error', '重发生成失败: ' + e.message);
                isResending = false;
                return { ok: false, text: cur, messageId: targetId };
            } finally { isResending = false; }
        }
        return { ok: true, text: cur, messageId: targetId };
    }

