    // ============ TTS前八股修正 ============
    function normalizeBaguCorrections(value) {
        if (typeof value === 'string') {
            try { return normalizeBaguCorrections(JSON.parse(value)); } catch (e) { return null; }
        }
        if (value && !Array.isArray(value) && typeof value === 'object') {
            var wrapped = value.corrections || value.items || value.replacements || value.results || value.data || value.output;
            if (wrapped !== undefined) return normalizeBaguCorrections(wrapped);
            if (value.original !== undefined || value.corrected !== undefined) value = [value];
            else return null;
        }
        if (!Array.isArray(value)) return null;
        if (!value.length) return [];
        var recognized = 0;
        var list = value.map(function(x) {
            if (!x || typeof x !== 'object') return null;
            var original = x.original;
            if (typeof original !== 'string') original = x.before !== undefined ? x.before : x.source;
            var corrected = x.corrected;
            if (typeof corrected !== 'string') corrected = x.after !== undefined ? x.after : x.replacement;
            if (typeof original !== 'string' || typeof corrected !== 'string') return null;
            recognized++;
            return { original: original, corrected: corrected };
        }).filter(function(x) {
            return x && x.original && x.original !== x.corrected;
        }).slice(0, 200);
        return recognized ? list : null;
    }

    function findBalancedJsonParts(source) {
        var parts = [];
        for (var start = 0; start < source.length; start++) {
            var opening = source[start];
            if (opening !== '[' && opening !== '{') continue;
            var stack = [], inString = false, escaped = false;
            for (var i = start; i < source.length; i++) {
                var ch = source[i];
                if (inString) {
                    if (escaped) escaped = false;
                    else if (ch === '\\') escaped = true;
                    else if (ch === '"') inString = false;
                    continue;
                }
                if (ch === '"') { inString = true; continue; }
                if (ch === '[' || ch === '{') stack.push(ch);
                else if (ch === ']' || ch === '}') {
                    var expected = ch === ']' ? '[' : '{';
                    if (stack.pop() !== expected) break;
                    if (!stack.length) {
                        parts.push(source.slice(start, i + 1));
                        start = i;
                        break;
                    }
                }
            }
        }
        return parts;
    }

    function parseBaguResponse(raw) {
        if (typeof raw !== 'string' || !raw.trim()) return null;
        var candidates = [], m;
        var refineRe = /<refine>([\s\S]*?)<\/refine>/gi;
        while ((m = refineRe.exec(raw)) !== null) candidates.push(m[1]);
        var codeRe = /```(?:json)?\s*([\s\S]*?)```/gi;
        while ((m = codeRe.exec(raw)) !== null) candidates.push(m[1]);
        candidates.push(raw);
        for (var i = 0; i < candidates.length; i++) {
            var source = candidates[i].trim();
            var jsonParts = [source].concat(findBalancedJsonParts(source));
            for (var j = 0; j < jsonParts.length; j++) {
                var variants = [jsonParts[j], jsonParts[j].replace(/,\s*([}\]])/g, '$1')];
                for (var k = 0; k < variants.length; k++) {
                    try {
                        var normalized = normalizeBaguCorrections(JSON.parse(variants[k]));
                        if (normalized !== null) return normalized;
                    } catch (e) {}
                }
            }
        }
        return null;
    }

