    function applyBaguCorrections(text, list) {
        var out = text, count = 0, matched = [];
        function escRe(s) {
            var special = '\\^$.*+?()[]{}|';
            return Array.from(s).map(function(ch) { return special.indexOf(ch) !== -1 ? '\\' + ch : ch; }).join('');
        }
        for (var i = 0; i < list.length; i++) {
            var original = list[i].original, corrected = list[i].corrected;
            if (!original) continue;
            if (out.indexOf(original) !== -1) {
                var exactHits = out.split(original).length - 1;
                out = out.split(original).join(corrected); count += exactHits;
                matched.push({ original: original, corrected: corrected, occurrences: exactHits }); continue;
            }
            var normalized = original.replace(/\s+/g, ' ').trim();
            if (normalized) {
                try {
                    var flexible = new RegExp(normalized.split(' ').map(escRe).join('\\s+'), 'g');
                    var flexibleHits = out.match(flexible);
                    var next = out.replace(flexible, corrected);
                    if (next !== out) {
                        var flexibleCount = flexibleHits ? flexibleHits.length : 1;
                        out = next; count += flexibleCount;
                        matched.push({ original: original, corrected: corrected, occurrences: flexibleCount }); continue;
                    }
                } catch (e) {}
            }
            var collapsed = original.replace(/\s+/g, '');
            if (collapsed.length > 3 && out.replace(/\s+/g, '').indexOf(collapsed) !== -1) {
                try {
                    var chars = Array.from(original).map(escRe);
                    var folded = new RegExp(chars.join('\\s*'), 'g');
                    var foldedHits = out.match(folded);
                    var next2 = out.replace(folded, corrected);
                    if (next2 !== out) {
                        var foldedCount = foldedHits ? foldedHits.length : 1;
                        out = next2; count += foldedCount;
                        matched.push({ original: original, corrected: corrected, occurrences: foldedCount });
                    }
                } catch (e) {}
            }
        }
        return { text: out, count: count, matched: matched };
    }

    function buildBaguCoverageHints(text) {
        var patterns = [
            /不是[^。！？!?\n]{1,48}?(?:而是|，?是)[^。！？!?\n]{1,48}/g,
            /(?:像|如同|好似)[^。！？!?\n]{1,42}?(?:一样|一般|似的)/g,
            /(?:仿佛|宛如|好像|某种|难以言说|精密仪器|机械般|机械一样)/g
        ];
        var hints = [], seen = {};
        function sentenceAt(index) {
            var left = index, right = index;
            while (left > 0 && !/[。！？!?\n]/.test(text[left - 1])) left--;
            while (right < text.length && !/[。！？!?\n]/.test(text[right])) right++;
            if (right < text.length) right++;
            var sentence = text.slice(left, right).trim();
            if (sentence.length > 140) sentence = sentence.slice(0, 140) + '…';
            return sentence;
        }
        for (var p = 0; p < patterns.length && hints.length < 30; p++) {
            var re = patterns[p], match;
            while ((match = re.exec(text)) !== null && hints.length < 30) {
                var sentence = sentenceAt(match.index);
                if (sentence && !seen[sentence]) { seen[sentence] = true; hints.push(sentence); }
                if (!match[0]) re.lastIndex++;
            }
        }
        return hints;
    }

    function extractBaguScope(text, cfg) {
        var startTag = String(cfg.extractStart || '').trim();
        var endTag = String(cfg.extractEnd || '').trim();
