    async function fetchBaguModels(apiUrl, apiKey) {
        var root = normalizeBaguApiRoot(apiUrl), key = String(apiKey || '').trim();
        var helperError = null;
        var modelListFn = typeof getModelList === 'function' ? getModelList
            : window.TavernHelper && typeof window.TavernHelper.getModelList === 'function' ? window.TavernHelper.getModelList.bind(window.TavernHelper) : null;
        // 酒馆助手会使用自定义API连接层请求，可处理浏览器直接fetch遇到的CORS限制。
        if (modelListFn) {
            try {
                var helperModels = normalizeBaguModelList(await modelListFn({ apiurl: root, key: key || undefined }));
                helperModels._via = 'tavern';
                return helperModels;
            } catch (e) { helperError = e; }
        }
        try {
            var headers = {};
            if (key) headers.Authorization = 'Bearer ' + key;
            var fetchFn = window.parent && typeof window.parent.fetch === 'function' ? window.parent.fetch.bind(window.parent) : fetch;
            var response = await fetchFn(root + '/models', { method: 'GET', headers: headers });
            if (!response.ok) throw new Error('HTTP ' + response.status);
            var directModels = normalizeBaguModelList(await response.json());
            directModels._via = 'browser';
            return directModels;
        } catch (directError) {
            var directMessage = directError && directError.message ? directError.message : String(directError);
            var helperMessage = helperError && helperError.message ? helperError.message : helperError ? String(helperError) : '';
            if (/failed to fetch|networkerror|load failed/i.test(directMessage)) {
                throw new Error('服务端禁止网页跨域读取模型列表' + (helperMessage ? '，酒馆代拉取也失败：' + helperMessage : '') + '；仍可手动填写模型');
            }
