            var result = await Promise.race([generateRaw(testCfg), timeout]);
            if (result === undefined || result === null || String(result).trim() === '') throw new Error('接口返回为空');
            return { source: source, text: String(result).trim().slice(0, 80) };
        } finally {
            if (timer) clearTimeout(timer);
            baguGenerationIds = baguGenerationIds.filter(function(x) { return x !== genId; });
        }
    }

    async function correctBaguBeforeTTS(text, messageId, token, chatText) {
        var cfg = settings.bagu || DEFAULTS.bagu;
        var sourceChatText = typeof chatText === 'string' ? chatText : text;
        function pass(status) { return { text: text, chatText: sourceChatText, baguStatus: status || 'skipped' }; }
        if (!cfg.enabled || !text) return pass();
        releaseStaleTTSMusicPause('八股修正 #' + messageId + ' 开始前');
        if (Number(messageId) === 0 && cfg.skipFloorZero !== false) {
            addLog('info', '八股修正 #0 已按设置跳过（角色开场白仍可正常朗读）');
            return pass();
        }
        var checked = getCheckedBaguVersion(messageId, sourceChatText, cfg);
        if (checked) {
            addLog('info', '八股修正 #' + messageId + ' 同一版本已处理，跳过重复检查');
            return { text: checked.text || text, chatText: sourceChatText, baguStatus: 'cached' };
        }
        var reviewText = extractBaguScope(text, cfg);
        if (!reviewText || reviewText.length < Math.max(0, cfg.minLength || 0)) return pass();
        if (typeof generateRaw !== 'function') {
            addLog('warn', '八股修正不可用：generateRaw未找到，放行原文');
            return pass('failed');
        }
        var coverageHints = buildBaguCoverageHints(reviewText);
        var coverageSuffix = coverageHints.length
            ? '\n\n[本地预扫描发现 ' + coverageHints.length + ' 段高风险表达，请逐段判断；这只是提示，仍需检查全文]\n- ' + coverageHints.join('\n- ')
            : '';
        var genId = 'ta_bagu_' + messageId + '_' + Date.now();
        var genCfg = {
            generation_id: genId,
            should_silence: true,
            max_chat_history: 0,
            ordered_prompts: [
                { role: 'system', content: (cfg.prompt || BAGU_DEFAULT_PROMPT) + '\n\n覆盖度要求：必须从头到尾逐段扫描，不要只返回最典型的一处，也不要把结果当作示例；每个确认命中的独立问题都应列入数组。\n格式硬性要求：最外层必须直接输出 JSON 数组；无需修改时输出 []；禁止额外说明、代码块或对象包装。' },
                { role: 'user', content: '[以下是待朗读正文，只检查这段文字]\n' + reviewText + coverageSuffix }
            ]
        };
        var resolvedSource = '';
        if (cfg.apiUrl) {
            resolvedSource = resolveBaguApiSource(cfg);
            genCfg.custom_api = {
                apiurl: normalizeBaguApiRoot(cfg.apiUrl),
                source: resolvedSource,
                // 推理模型的思考 token 与最终 JSON 共用额度；额度过小会只返回思考而没有正文。
                max_tokens: 8192,
                temperature: 0.2
            };
            if (cfg.apiKey) genCfg.custom_api.key = cfg.apiKey;
            if (cfg.model) genCfg.custom_api.model = cfg.model;
        } else if (cfg.model) {
            genCfg.custom_api = { model: cfg.model };
        }
        baguGenerationIds.push(genId);
        showBaguWorking(genId, messageId, reviewText.length);
        var timer = null, timeoutMs = Math.max(10000, cfg.timeoutMs || 180000);
        var requestStartedAt = 0, requestElapsedMs = 0, responseChars = 0;
        if (isSlowReasoningBaguModel(cfg)) timeoutMs = Math.max(timeoutMs, 180000);
        addLog('info', '八股修正 #' + messageId + ' 开始 (检查' + reviewText.length + '字 / 预扫描' + coverageHints.length + '段 / 朗读' + text.length + '字' + (resolvedSource ? ' / ' + baguApiSourceLabel(resolvedSource) + ' / ' + (cfg.model || '默认模型') : '') + ')');
        try {
            var timeoutP = new Promise(function(_, reject) {
                timer = setTimeout(function() {
                    try { stopGenerationById(genId); } catch (e) {}
                    reject(new Error('超时 ' + Math.round(timeoutMs / 1000) + '秒' + (resolvedSource ? '（协议：' + baguApiSourceLabel(resolvedSource) + '，模型：' + (cfg.model || '默认') + '）' : '')));
                }, timeoutMs);
            });
            requestStartedAt = Date.now();
            var raw = await Promise.race([generateRaw(genCfg), timeoutP]);
            requestElapsedMs = Date.now() - requestStartedAt;
            responseChars = typeof raw === 'string' ? raw.length : 0;
            if (token !== activeSession) return null;
            if (!settings.bagu.enabled) return pass();
            if (typeof raw !== 'string' || !raw.trim()) {
                throw new Error('模型未返回正文（输出额度可能全部用于推理），本次不记为已检查');
            }
            var list = parseBaguResponse(raw);
            if (list === null) {
                throw new Error('模型返回内容不是有效的修正JSON，本次不记为已检查；返回片段：' + baguResponsePreview(raw));
            }
            addLog('info', '八股API #' + messageId + ' 返回 ' + responseChars + '字 / 解析' + list.length + '条 / ' + (requestElapsedMs / 1000).toFixed(1) + '秒');
            if (!list.length) {
                rememberCheckedBaguVersion(messageId, sourceChatText, text, cfg);
                addLog('info', '八股修正 #' + messageId + ' 无需修改');
                return pass('nochange');
            }
            var applied = applyBaguCorrectionsInScope(text, cfg, list);
            var chatApplied = applyBaguCorrectionsInScope(sourceChatText, cfg, applied.matched);
            var unmatchedCount = Math.max(0, list.length - applied.matched.length);
            var chatUpdated = false, chatError = '';
            if (cfg.rewriteChat && chatApplied.count > 0 && typeof setChatMessages === 'function') {
                var hadProc = Object.prototype.hasOwnProperty.call(procIds, messageId);
                var oldProc = procIds[messageId], oldProcessed = processedVersions[messageId];
                var rewrittenVersion = textFingerprint(chatApplied.text);
                // 写回可能同步触发消息事件；提前登记新版指纹，防止修正自己再次修正。
                procIds[messageId] = rewrittenVersion;
                processedVersions[messageId] = rewrittenVersion;
                try {
                    await setChatMessages([{ message_id: messageId, message: chatApplied.text }], { refresh: 'affected' });
                    chatUpdated = true;
                    if (!hadProc) delete procIds[messageId];
                    addLog('info', '八股修正 #' + messageId + ' 已写回聊天楼层 (' + chatApplied.count + '处)');
                } catch (writeError) {
                    if (hadProc) procIds[messageId] = oldProc; else delete procIds[messageId];
                    if (oldProcessed === undefined) delete processedVersions[messageId]; else processedVersions[messageId] = oldProcessed;
                    chatError = writeError.message || String(writeError);
                    addLog('warn', '八股修正 #' + messageId + ' 楼层写回失败，仍朗读修正版: ' + chatError);
                }
            }
            if (list.length > 0) {
                saveBaguHistoryEntry({
                    messageId: messageId,
                    time: new Date().toLocaleString(),
                    items: applied.matched,
                    ttsCount: applied.count,
                    chatCount: chatApplied.count,
                    modelCount: list.length,
                    unmatchedCount: unmatchedCount,
                    responseChars: responseChars,
                    elapsedMs: requestElapsedMs,
                    coverageHints: coverageHints.length,
                    rewriteRequested: cfg.rewriteChat !== false,
                    chatUpdated: chatUpdated,
                    chatError: chatError
                });
            }
            var finalChatText = chatUpdated ? chatApplied.text : sourceChatText;
            rememberCheckedBaguVersion(messageId, finalChatText, applied.text || text, cfg);
            addLog('info', '八股修正 #' + messageId + ' 模型返回 ' + list.length + '条，匹配' + applied.matched.length + '条，实际替换 ' + applied.count + '处，未匹配' + unmatchedCount + '条');
            return { text: applied.text || text, chatText: finalChatText, baguStatus: 'corrected' };
        } catch (e) {
            if (token !== activeSession) return null;
            addLog('warn', '八股修正 #' + messageId + ' 失败，放行原文: ' + (e.message || e));
            return pass('failed');
        } finally {
            if (timer) clearTimeout(timer);
            baguGenerationIds = baguGenerationIds.filter(function(x) { return x !== genId; });
            hideBaguWorking(genId);
        }
    }
    function onPlayerStart(item, audio) {
        if (bgm && bgm.pauseForTTS(audio)) addLog('info', 'TTS #' + (item && item.id || '') + ' 已实际开始播放，背景音乐暂停');
        if (isResending || !settings.autoSend.enabled || !item || !item.id || settings.autoRead) return;
        if (!/^msg-\d+$/.test(String(item.id))) return;
        addLog('info', '语音已开始播放 #' + (item.id || '') + '，立即发送下一轮');
        advanceCycle(item.id);
    }
    function onPlayerFailure(item) {
        if (!item || !/^msg-\d+$/.test(String(item.id))) return;
        addLog('warn', '音频播放失败 #' + item.id + '，使用兜底推进');
        advanceCycle(item.id, '音频播放失败');
    }

    async function processAI(msg) {
        if (!msg || !msg.message || !msg.message.trim()) return;
        var mid = msg.message_id;
        if (isResending) { addLog('info', '正在重发中, 跳过消息 #' + mid); return; }
        var raw = msg.message;
        var incomingVersion = textFingerprint(raw);
        if (processedVersions[mid] === incomingVersion || procIds[mid] === incomingVersion) return;
        var passiveEnabled = settings.bagu.enabled || settings.textResend.enabled;
        if (!settings.running && !settings.autoRead && !cyclePaused && !passiveEnabled) return;
        procIds[mid] = incomingVersion;
        var token = activeSession, processedText = raw, processedMid = mid;

        if (settings.autoRead) {
            addLog('info', '自动阅读 #' + mid + ' (' + raw.length + '字)');
            try {
                if (settings.tts.enabled || settings.bagu.enabled) {
                    var fc = settings.textFilter;
                    var regexOn = settings.regexFilter.enabled;
                    var text = filterText(raw, { readOn: fc.enabled && fc.readEnabled, read: fc.readRanges || [], skipOn: fc.enabled && fc.skipEnabled, skip: fc.skipRanges || [] }, regexOn);
                    if (regexOn) { text = applyRegexes(text); text = stripHtml(text).trim(); }
                    if (text) {
                        if (text.length !== raw.length) addLog('info', '文本过滤 ' + raw.length + '→' + text.length + '字');
                        if (settings.bagu.enabled) {
                            var baguResult = await correctBaguBeforeTTS(text, mid, token, raw);
                            if (baguResult === null || token !== activeSession) return;
                            text = baguResult.text; processedText = baguResult.chatText;
                        }
                        if (settings.tts.enabled) doTTS(mid, text, false, token);
                    } else addLog('warn', '消息 #' + mid + ' 过滤后为空，跳过八股修正与TTS');
                }
            } catch (e) { addLog('error', '自动阅读 #' + mid + ' 失败: ' + e.message); }
            finally { if (token === activeSession) processedVersions[processedMid] = textFingerprint(processedText); delete procIds[mid]; }
            return;
        }

        addLog('info', '收到AI消息 #' + mid + ' (' + raw.length + '字)');
        try {
            var rs = await ensureTags(raw, mid, token);
            processedText = rs.text || raw;
            processedMid = rs.messageId === undefined || rs.messageId === null ? mid : rs.messageId;
            passiveEnabled = settings.bagu.enabled || settings.textResend.enabled;
            if (!rs.ok || (!settings.running && !cyclePaused && !passiveEnabled)) { delete procIds[mid]; return; }

            lastDreamQuestions = parseDreamQuestions(rs.text);
            if (lastDreamQuestions.length) addLog('info', '检测到 ' + lastDreamQuestions.length + ' 个梦境共创问题');
            var optMatch = rs.text.match(/<options>([\s\S]*?)<\/options>/i);
            if (optMatch) {
                lastOptions = optMatch[1].split('|').map(function(s) { return s.trim(); }).filter(function(s) { return s; });
                addLog('info', '检测到 ' + lastOptions.length + ' 个可发送选项');
            } else lastOptions = null;

            // “启用”只表示能力可用；TTS必须由循环/自动阅读任务启动。
            // 暂停循环时允许当前已经收到的回复完成朗读，但不会推进下一轮。
            var ttsTaskActive = settings.tts.enabled && (settings.running || cyclePaused);
            var needsTextPipeline = ttsTaskActive || settings.bagu.enabled;
            if (needsTextPipeline) {
                var fc = settings.textFilter;
                var regexOn = settings.regexFilter.enabled;
                var text = filterText(rs.text, { readOn: fc.enabled && fc.readEnabled, read: fc.readRanges || [], skipOn: fc.enabled && fc.skipEnabled, skip: fc.skipRanges || [] }, regexOn);
                if (regexOn) { text = applyRegexes(text); text = stripHtml(text).trim(); }
                if (text) {
                    if (text.length !== rs.text.length) addLog('info', '文本过滤 ' + rs.text.length + '→' + text.length + '字');
                    if (settings.bagu.enabled) {
                        var baguResult = await correctBaguBeforeTTS(text, processedMid, token, rs.text);
                        if (baguResult === null || token !== activeSession) return;
                        text = baguResult.text; processedText = baguResult.chatText;
                    }
                    if (ttsTaskActive) doTTS(processedMid, text, true, token);
                    else if (settings.running || cyclePaused) advanceCycle(processedMid, settings.bagu.enabled ? '八股修正完成（TTS未启用）' : 'TTS未启用');
                    else if (settings.bagu.enabled) addLog('info', '八股流程 #' + processedMid + ' 已结束；未启动阅读任务，不进行TTS');
                } else {
                    addLog('warn', '消息 #' + mid + ' 过滤后为空，跳过八股修正与TTS');
                    if (settings.running || cyclePaused) advanceCycle(processedMid, '过滤后无可处理文本');
                }
            } else if (settings.running || cyclePaused) advanceCycle(processedMid, 'TTS与八股修正均未启用');
        } catch (e) {
            addLog('error', '处理消息 #' + mid + ' 失败: ' + e.message);
            advanceCycle(processedMid, '消息处理异常');
        } finally {
            if (token === activeSession) processedVersions[processedMid] = textFingerprint(processedText);
            delete procIds[mid];
        }
    }
    var msgDebounce = null;
    function onMsgReceived() {
        if (isRangeReading) return;
        if (!settings.running && !settings.autoRead && !cyclePaused && !settings.bagu.enabled && !settings.textResend.enabled) return;
        if (msgDebounce) clearTimeout(msgDebounce);
        msgDebounce = setTimeout(function() {
            msgDebounce = null;
            var m = getLatestAI();
            if (m) {
                if (regenMid && m.message_id === regenMid) {
                    addLog('info', '跳过已重发的消息 #' + m.message_id);
                    regenMid = null;
                    return;
                }
                addLog('info', '消息事件触发, 找到AI #' + m.message_id);
                processAI(m);
            } else {
                addLog('info', '消息事件触发, 未找到AI消息');
            }
        }, 300);
    }

    async function doTTS(mid, text, advanceOnFailure, token) {
        token = token === undefined ? activeSession : token;
        var voice = settings.tts.voice || 'female_1', rate = settings.tts.rate || 0, controller = null;
        addLog('tts', '合成 #' + mid + ' (' + text.length + '字, ' + voice + ')...');
        var key = cKey(text, voice, rate);
        var ri = rndInfo();
        try {
            var blob = await getCached(key);
            if (blob) {
                updateNowPlaying('<span>📦</span><span> #' + mid + '</span><span>' + ri.round + '</span><span> 从缓存读取...</span>');
                addLog('tts', '✓ #' + mid + ' 命中缓存');
            } else {
                updateNowPlaying('<span>⏳</span><span> #' + mid + '</span><span>' + ri.round + '</span><span> 正在合成...</span>');
                controller = new AbortController();
                trackController(controller);
                blob = await synTTS(text, voice, rate, controller.signal);
                untrackController(controller); controller = null;
                if (token !== activeSession) return false;
                setCached(key, blob).catch(function() {});
            }
            if (token !== activeSession) return false;
            player.enqueue({ id: 'msg-' + mid, blob: blob, text: text });
            addLog('tts', '✓ #' + mid + ' 合成完成，入队');
            return true;
        } catch (e) {
            if (controller) untrackController(controller);
            if (e && e.name === 'AbortError') { addLog('info', 'TTS已取消 #' + mid); return false; }
            addLog('error', 'TTS失败 #' + mid + ': ' + e.message);
            hideNowPlaying();
            if (advanceOnFailure && token === activeSession) advanceCycle(mid, 'TTS合成失败');
            return false;
        }
    }

