    // ============ 范围朗读 ============
    async function readRange(startFloor, endFloor) {
        if (!settings.tts.enabled) {
            toastr && toastr.warning && toastr.warning('范围朗读需要先启用TTS朗读', 'TTS自动循环');
            currentTab = 'tts'; refreshPanel();
            return;
        }
        if (settings.running || cyclePaused || settings.autoRead) {
            toastr && toastr.warning && toastr.warning('请先停止循环或自动阅读', 'TTS自动循环');
            return;
        }
        if (isRangeReading) {
            toastr && toastr.info && toastr.info('范围朗读正在进行', 'TTS自动循环');
            return;
        }
        isRangeReading = true;
        var token = ++rangeReadToken;
        var sessionToken = beginSession();
        var msgs = getAIMessagesByRange(startFloor, endFloor);
        addLog('info', '===== 范围朗读 ' + startFloor + '→' + endFloor + '楼 =====');
        if (!msgs.length) {
            addLog('warn', '范围朗读: 指定楼层无AI消息');
            toastr && toastr.warning && toastr.warning('指定范围内无AI消息', 'TTS自动循环');
            isRangeReading = false;
            refreshPanel();
            return;
        }
        player.clear();
        startBGMForTask();
        addLog('info', '范围朗读: 共 ' + msgs.length + ' 条，按顺序合成');
        toastr && toastr.info && toastr.info('准备朗读 ' + msgs.length + ' 条消息', 'TTS自动循环');
        var fc = settings.textFilter;
        var regexOn = settings.regexFilter.enabled;
        refreshPanel();
        for (var i = 0; i < msgs.length; i++) {
            if (token !== rangeReadToken) return;
            rangeProgressText = '正在准备 ' + (i + 1) + '/' + msgs.length;
            refreshPanel();
            var msg = msgs[i];
            var raw = msg.message || '';
            if (!raw.trim()) continue;
            var text = filterText(raw, { readOn: fc.enabled && fc.readEnabled, read: fc.readRanges || [], skipOn: fc.enabled && fc.skipEnabled, skip: fc.skipRanges || [] }, regexOn);
            if (regexOn) { text = applyRegexes(text); text = stripHtml(text).trim(); }
            if (!text) continue;
            var baguResult = await correctBaguBeforeTTS(text, msg.message_id, sessionToken, raw);
            if (baguResult === null || sessionToken !== activeSession) return;
            text = baguResult.text;
            await doTTS('rng-' + msg.message_id, text, false, sessionToken);
            if (token !== rangeReadToken) { if (player) player.clear(); return; }
        }
        if (token !== rangeReadToken) return;
        isRangeReading = false;
        rangeProgressText = '';
        addLog('info', '范围朗读: 全部按顺序入队完毕');
        refreshPanel();
    }

    function stopRangeReading() {
        if (!isRangeReading) return;
        rangeReadToken++;
        beginSession();
        isRangeReading = false;
        rangeProgressText = '';
        if (player) player.clear();
        stopBGMForTask();
        addLog('info', '范围朗读已停止');
        refreshPanel();
        toastr && toastr.info && toastr.info('范围朗读已停止', 'TTS自动循环');
    }

    // ============ 启动/停止 ============
    function bootstrapFromLatestMessage() {
        if (!settings.autoSend.bootstrapLast) return false;
        var latest = getLatestMessage();
        if (!latest) return false;
        if (latest.role === 'assistant' && latest.message && latest.message.trim()) {
            addLog('info', '启动接管最后一楼AI消息 #' + latest.message_id + '：先解析并朗读，语音开始后发送下一轮');
            processAI(latest);
            return true;
        }
        if (latest.role === 'user') {
            addLog('info', '最后一楼是用户消息 #' + latest.message_id + '，等待对应AI回复，不额外发送启动文本');
            toastr && toastr.info && toastr.info('正在等待最后一楼用户消息的AI回复', 'TTS自动循环');
            return true;
        }
        return false;
    }

    function startCycle() {
        if (cyclePaused) { resumeCycle(); return; }
        if (!settings.autoSend.enabled) {
            toastr && toastr.warning && toastr.warning('请先启用自动发送，循环才有可执行内容', 'TTS自动循环');
            currentTab = 'send'; refreshPanel(); return;
        }
        if (isRangeReading) {
            toastr && toastr.warning && toastr.warning('请先停止范围朗读', 'TTS自动循环');
            return;
        }
        var rounds = settings.autoSend.maxRounds > 0 ? settings.autoSend.maxRounds + '轮' : '无限轮';
        var modeText = settings.autoSend.optionMode === 'random' ? '优先随机发送AI选项' : settings.autoSend.optionMode === 'pick' ? '优先发送第' + (settings.autoSend.optionIndex || 1) + '个AI选项' : settings.autoSend.optionMode === 'dream' ? '为每个梦境共创问题随机选择一个回答' : '发送固定文本「' + (settings.autoSend.text || '继续') + '」';
        var bootstrapText = settings.autoSend.bootstrapLast ? '启动时优先接管最后一楼；没有可接管内容才发送固定文本' : '启动后立即发送固定文本';
        var summary = '即将启动循环（' + rounds + '，' + modeText + '）。' + bootstrapText + '「' + (settings.autoSend.text || '继续') + '」。是否继续？';
        if (!window.parent.confirm(summary)) return;
        if (settings.autoRead) stopAutoRead();
        settings.running = true;
        cyclePaused = false;
        beginSession();
        resetState();
        saveSettings();
        startBGMForTask();
        addLog('info', '循环已启动');
        refreshPanel();
        if (!bootstrapFromLatestMessage()) doAutoSend();
        toastr && toastr.success && toastr.success('TTS自动循环已启动', 'TTS自动循环');
    }

    function resumeCycle() {
        if (!cyclePaused) return;
        settings.running = true;
        cyclePaused = false;
        cycleCompleted = false;
        saveSettings();
        addLog('info', '循环已继续');
        refreshPanel();
        if (pendingAdvanceId) {
            var id = pendingAdvanceId;
            pendingAdvanceId = null;
            advanceCycle(id, '恢复暂停任务');
        }
        toastr && toastr.success && toastr.success('循环已继续', 'TTS自动循环');
    }

    function stopCycle() {
        settings.running = false;
        cyclePaused = false;
        beginSession();
        resetState();
        if (player) player.clear();
        if (msgDebounce) { clearTimeout(msgDebounce); msgDebounce = null; }
        stopBGMForTask();
        saveSettings();
        addLog('info', '循环已终止（含TTS）');
        refreshPanel();
        toastr && toastr.info && toastr.info('TTS自动循环已终止', 'TTS自动循环');
    }

    function onChatChanged() {
        var hadTask = settings.running || cyclePaused || settings.autoRead || isRangeReading;
        settings.running = false; settings.autoRead = false; cyclePaused = false; isRangeReading = false;
        rangeReadToken++; rangeProgressText = '';
        uiPreview = { filter: null, bagu: null };
        baguCheckedVersions = {};
        beginSession(); resetState();
        if (player) player.clear();
        if (bgm) bgm.pauseManual(false);
        saveSettings(); syncRegexes(); refreshPanel();
        if (hadTask) addLog('info', '聊天已切换，旧聊天任务已安全停止');
    }

    function pauseCycle() {
        settings.running = false;
        cyclePaused = true;
        saveSettings();
        addLog('info', '循环已暂停：当前回复和TTS继续处理，不再发送下一轮');
        refreshPanel();
        toastr && toastr.info && toastr.info('已暂停；点击继续后再发送下一轮', 'TTS自动循环');
    }

    function startAutoRead() {
        if (!settings.tts.enabled) {
            toastr && toastr.warning && toastr.warning('自动阅读需要先启用TTS朗读', 'TTS自动循环');
            currentTab = 'tts'; refreshPanel();
            return;
        }
        if (cyclePaused) {
            toastr && toastr.warning && toastr.warning('请先终止已暂停的循环', 'TTS自动循环');
            return;
        }
        if (isRangeReading) stopRangeReading();
        settings.autoRead = true;
        settings.running = false;
        beginSession();
        startBGMForTask();
        resetState();
        saveSettings();
        addLog('info', '自动阅读已启动');
        refreshPanel();
        var m = getLatestAI();
        if (m && m.message && m.message.trim()) processAI(m);
        toastr && toastr.success && toastr.success('自动阅读已启动', 'TTS自动循环');
    }

    function stopAutoRead() {
        settings.autoRead = false;
        beginSession();
        if (player) player.clear();
        stopBGMForTask();
        saveSettings();
        addLog('info', '自动阅读已停止');
        refreshPanel();
        toastr && toastr.info && toastr.info('自动阅读已停止', 'TTS自动循环');
    }

    // ============ UI ============
    function PD() { return window.parent.document; }

    function rndInfo() {
        var r = ' #?';
        var maxR = settings.autoSend.maxRounds || 0;
        return { mid: r, round: maxR > 0 ? ' [' + roundCount + '/' + maxR + ']' : ' [' + roundCount + '/∞]' };
    }

    function rndInfoFromItem(item) {
        var mid = '';
        if (item && item.id) { mid = ' #' + String(item.id).replace('msg-', ''); }
        var maxR = settings.autoSend.maxRounds || 0;
        return { mid: mid, round: maxR > 0 ? ' [' + roundCount + '/' + maxR + ']' : ' [' + roundCount + '/∞]' };
    }

    function getTaskStack() {
        var stack = PD().getElementById('ta-task-stack');
        if (!stack) {
            stack = PD().createElement('div');
            stack.id = 'ta-task-stack';
            $(PD().body).append(stack);
        }
        return stack;
    }

    function renderTaskStatus() {
        var stack = getTaskStack();
        var el = PD().getElementById('ta-task-status');
        if (!el) {
            el = PD().createElement('div');
            el.id = 'ta-task-status';
            el.className = 'ta-task-card';
            stack.insertBefore(el, stack.firstChild || null);
        }
        var html = '', action1 = '', action2 = '';
        if (settings.running) {
            var maxR = settings.autoSend.maxRounds || 0;
            html = '<span class="ta-task-icon">🔄</span><span><b>自动循环运行中</b><small>第 ' + roundCount + '/' + (maxR || '∞') + ' 轮</small></span>';
            action1 = '<button data-action="pause">暂停</button>';
            action2 = '<button data-action="stop-cycle">终止</button>';
        } else if (cyclePaused) {
            html = '<span class="ta-task-icon">⏸</span><span><b>自动循环已暂停</b><small>当前回复可继续收尾，不发送下一轮</small></span>';
            action1 = '<button data-action="resume">继续</button>';
            action2 = '<button data-action="stop-cycle">终止</button>';
        } else if (settings.autoRead) {
            html = '<span class="ta-task-icon">📖</span><span><b>自动阅读运行中</b><small>只朗读新回复，不自动发送</small></span>';
            action2 = '<button data-action="stop-read">停止</button>';
        } else if (isRangeReading) {
            html = '<span class="ta-task-icon">📚</span><span><b>范围朗读运行中</b><small>' + escH(rangeProgressText || '正在准备消息') + '</small></span>';
            action2 = '<button data-action="stop-range">停止</button>';
        } else {
            el.classList.remove('visible');
            return;
        }
        el.innerHTML = html + '<span class="ta-task-actions">' + action1 + action2 + '</span>';
        el.classList.add('visible');
        var buttons = el.querySelectorAll('button[data-action]');
        for (var i = 0; i < buttons.length; i++) buttons[i].onclick = function() {
            var action = this.getAttribute('data-action');
            if (action === 'pause') pauseCycle();
            else if (action === 'resume') resumeCycle();
            else if (action === 'stop-cycle') stopCycle();
            else if (action === 'stop-read') stopAutoRead();
            else if (action === 'stop-range') stopRangeReading();
        };
    }

    function updateNowPlaying(html) {
        var el = PD().getElementById('ta-now-playing');
        if (!el) {
            el = PD().createElement('div');
            el.id = 'ta-now-playing';
            el.className = 'ta-task-card';
            getTaskStack().appendChild(el);
        }
        el.innerHTML = html;
        el.classList.add('visible');
    }

    function showNowPlaying(item) {
        var ri = rndInfoFromItem(item);
        var preview = '';
        if (item && item.text) preview = item.text.replace(/[\r\n]/g, ' ').slice(0, 28);
        updateNowPlaying('<span>🔊</span><span>' + ri.mid + '</span><span>' + ri.round + '</span><span> ' + escH(preview) + (item && item.text && item.text.length > 28 ? '...' : '') + '</span>');
    }

    function hideNowPlaying() {
        var el = PD().getElementById('ta-now-playing');
        if (el) el.classList.remove('visible');
    }

