    function workflowSteps(s, mode) {
        var steps = [{ label: 'AI回复', core: true }];
        if (s.textResend.enabled) steps.push({ label: '缺失标签重发' });
        var hasTextConsumer = s.tts.enabled || (s.bagu && s.bagu.enabled);
        if (hasTextConsumer && s.textFilter.enabled) steps.push({ label: '文本过滤' });
        if (hasTextConsumer && s.regexFilter.enabled) steps.push({ label: '正则处理' });
        if (s.bagu && s.bagu.enabled) {
            steps.push({ label: '八股修正', core: true });
            if (s.bagu.rewriteChat !== false) steps.push({ label: '写回楼层' });
        }
        if (s.tts.enabled) steps.push({ label: 'TTS朗读', core: true });
        if (mode === 'cycle' && s.autoSend.enabled) {
            if (s.tts.enabled) steps.push({ label: '语音开始' });
            steps.push({ label: '发送下一轮', core: true });
        }
        return steps;
    }

    function renderWorkflowPreview(s, mode) {
        var labels = { cycle: '自动循环', read: '自动阅读', range: '范围朗读' };
        var steps = workflowSteps(s, mode), parts = [];
        for (var i = 0; i < steps.length; i++) {
            if (i) parts.push('<span class="ta-step-arrow">→</span>');
            parts.push('<span class="ta-step' + (steps[i].core ? ' core' : '') + '">' + steps[i].label + '</span>');
        }
        var note = mode === 'cycle'
            ? (s.tts.enabled ? '语音真正开始播放时发送下一轮。' : 'TTS关闭时，在文本处理完成后发送下一轮。')
            : mode === 'read' ? '只处理并朗读新回复，不会自动发送。'
            : '按楼层顺序处理并加入语音队列，不会自动发送。';
        if (!s.tts.enabled && mode !== 'cycle') note = '当前未启用TTS；此模式启动后不会产生语音。';
        return '<div class="ta-workflow"><div class="ta-workflow-title"><b>本次执行流程</b><span>' + labels[mode] + '</span></div><div class="ta-workflow-steps">' + parts.join('') + '</div><div class="ta-workflow-note">' + note + '</div></div>';
