    function buildLatestPreview() {
        var msg = getLatestAI();
        if (!msg || !msg.message || !msg.message.trim()) return { error: '没有找到可预检的AI回复' };
        var raw = msg.message, fc = settings.textFilter;
        var ranged = filterText(raw, { readOn: fc.enabled && fc.readEnabled, read: fc.readRanges || [], skipOn: fc.enabled && fc.skipEnabled, skip: fc.skipRanges || [] }, true);
        var finalText = settings.regexFilter.enabled ? applyRegexes(ranged) : ranged;
        finalText = stripHtml(finalText).trim();
        var b = settings.bagu || DEFAULTS.bagu;
        var startTag = String(b.extractStart || '').trim(), endTag = String(b.extractEnd || '').trim();
        var startIndex = startTag ? finalText.indexOf(startTag) : 0;
        var startFound = !startTag || startIndex !== -1;
        var start = startFound && startTag ? startIndex + startTag.length : 0;
        var endIndex = endTag ? finalText.indexOf(endTag, start) : finalText.length;
        var endFound = !endTag || endIndex !== -1;
        var end = endFound && endTag ? endIndex : finalText.length;
        var scope = finalText.slice(start, end).trim();
        return { mid: msg.message_id, rawLength: raw.length, rangedLength: ranged.length, finalLength: finalText.length, scopeLength: scope.length, startTag: startTag, endTag: endTag, startFound: startFound, endFound: endFound, skipFloorZero: Number(msg.message_id) === 0 && b.skipFloorZero !== false, preview: scope.slice(0, 260) };
    }

