        }
        if (p.preview) html += '<details style="margin-top:5px;"><summary style="cursor:pointer;color:#aaa;">查看最终范围预览</summary><div class="ta-preview-text">' + escH(p.preview) + (p.scopeLength > 260 ? '…' : '') + '</div></details>';
