    function renderLogTab() {
        var bc = badLogCount();
        var filters = [{ id: 'all', name: '全部' }, { id: 'problem', name: '异常' }, { id: 'tts', name: 'TTS' }, { id: 'send', name: '发送' }, { id: 'info', name: '信息' }];
