        for (var f = 0; f < filters.length; f++) html += '<button class="ta-log-filter' + (logFilter === filters[f].id ? ' active' : '') + '" data-filter="' + filters[f].id + '">' + filters[f].name + '</button>';
        html += '</div><div class="ta-btn-group" style="margin-bottom:8px;"><button class="ta-btn ta-btn-sm ta-log-copy">📋 复制全部</button><button class="ta-btn ta-btn-sm ta-btn-danger ta-log-clear">🗑 清空</button><span style="color:#888;font-size:12px;margin-left:auto;">共 ' + logBuf.length + ' 条' + (bc > 0 ? '，' + bc + ' 条异常' : '') + '</span></div>';
        var visible = logBuf.filter(function(e) {
            if (logFilter === 'all') return true;
            if (logFilter === 'problem') return e.l === 'warn' || e.l === 'error';
            return e.l === logFilter;
        });
        if (!visible.length) return html + '<div class="ta-hint">当前筛选下暂无日志</div>';
        for (var i = visible.length - 1; i >= 0; i--) {
            var e = visible[i];
            html += '<div class="ta-log-entry"><span class="ta-log-time">' + escH(e.t) + '</span><span class="ta-log-icon">' + iconFor(e.l) + '</span><span class="ta-log-msg ta-log-' + e.l + '">' + escH(e.m) + '</span></div>';
        }
        return html;
    }

    function renderRegexTab(s) {
        var rx = syncedRegexes || [];
        var disabled = s.regexFilter.disabledIds || [];
        var aiRegexes = rx.filter(function(r) { return r.source && r.source.ai_output && r.destination && r.destination.display; });
        var html = '<div class="ta-section"><div class="ta-section-title"><span>🔧 正则过滤</span><label class="ta-toggle"><input class="ta-rx-toggle" type="checkbox"' + (s.regexFilter.enabled ? ' checked' : '') + '><span class="ta-toggle-slider"></span></label></div>';
        html += '<div class="' + (s.regexFilter.enabled ? '' : 'ta-disabled') + '">';
        if (s.regexFilter.enabled && !aiRegexes.length) {
            html += '<div style="color:#f0ad4e;font-size:12px;margin-bottom:8px;padding:6px 10px;background:rgba(240,173,78,.1);border:1px solid rgba(240,173,78,.3);border-radius:4px;">⚠ 正则过滤已开启，但尚未同步正则列表，点击下方按钮同步</div>';
        }
        html += '<div style="margin-bottom:8px;"><button class="ta-btn ta-btn-sm ta-rx-sync">🔄 同步正则</button> <span class="ta-hint" style="margin-left:4px;">从SillyTavern同步AI输出相关的正则脚本</span></div>';
        if (!aiRegexes.length) {
            html += '<div class="ta-hint">' + (rx.length ? '没有匹配「AI输出→显示」条件的正则' : '尚未同步，点击上方按钮同步') + '</div>';
        } else {
            for (var i = 0; i < aiRegexes.length; i++) {
                var r = aiRegexes[i];
                var isDisabled = disabled.indexOf(r.id) !== -1;
                var name = escH(r.script_name || '未命名');
                var findStr = escH(r.find_regex || '').slice(0, 60);
                html += '<div style="display:flex;align-items:center;gap:8px;margin-bottom:6px;padding:6px 8px;background:rgba(255,255,255,0.03);border-radius:4px;">';
                html += '<input class="ta-rx-item" type="checkbox" data-id="' + escH(r.id) + '"' + (!isDisabled ? ' checked' : '') + '>';
                html += '<div style="flex:1;min-width:0;"><div style="font-size:13px;font-weight:bold;">' + name + '</div>';
                html += '<div class="ta-hint" style="margin:0;font-size:11px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">/' + findStr + '/</div></div></div>';
            }
        }
        html += '</div></div>';
        return html;
    }


    function refreshPanel() {
        renderTaskStatus();
        if (!panelOpen) return;
        var panel = PD().getElementById(PANEL_ID);
        if (!panel) return;
        var body = panel.querySelector('#ta-panel-body');
        if (!body) return;
        var s = settings;
        function dot(on) { return on ? '<span style="color:#4ecdc4;font-size:9px;">●</span>' : ''; }
        var tabs = '<div class="ta-tabs">' +
            '<div class="ta-tab' + (currentTab === 'home' ? ' active' : '') + ' ta-tab-home">🏠 运行</div>' +
            '<div class="ta-tab' + (currentTab === 'send' ? ' active' : '') + ' ta-tab-send">📤 发送 ' + dot(s.autoSend.enabled) + '</div>' +
            '<div class="ta-tab' + (currentTab === 'tts' ? ' active' : '') + ' ta-tab-tts">🔊 TTS ' + dot(s.tts.enabled) + '</div>' +
            '<div class="ta-tab' + (currentTab === 'bagu' ? ' active' : '') + ' ta-tab-bagu">🧹 八股 ' + dot(s.bagu && s.bagu.enabled) + '</div>' +
            '<div class="ta-tab' + (currentTab === 'music' ? ' active' : '') + ' ta-tab-music">🎵 音乐 ' + dot(s.bgm && s.bgm.enabled) + '</div>' +
            '<div class="ta-tab' + (currentTab === 'filter' ? ' active' : '') + ' ta-tab-filter">✂ 过滤 ' + dot(s.textFilter.enabled) + '</div>' +
            '<div class="ta-tab' + (currentTab === 'resend' ? ' active' : '') + ' ta-tab-resend">🔄 重发 ' + dot(s.textResend.enabled) + '</div>' +
            '<div class="ta-tab' + (currentTab === 'regex' ? ' active' : '') + ' ta-tab-regex">🔧 正则 ' + dot(s.regexFilter.enabled) + '</div>' +
            '<div class="ta-tab' + (currentTab === 'log' ? ' active' : '') + ' ta-tab-log">🧾 日志' + (unreadLogAlerts > 0 ? '<span class="ta-badge">' + unreadLogAlerts + '</span>' : '') + '</div></div>';
        var content;
        switch (currentTab) {
            case 'home': content = renderHomeTab(s); break;
            case 'send': content = renderSendTab(s); break;
            case 'tts': content = renderTTSTab(s); break;
            case 'bagu': content = renderBaguTab(s); break;
            case 'music': content = renderMusicTab(s); break;
            case 'filter': content = renderFilterTab(s); break;
            case 'resend': content = renderResendTab(s); break;
            case 'regex': content = renderRegexTab(s); break;
            default: content = renderLogTab();
        }
        $(body).html(tabs + '<div class="ta-tab-content">' + content + '</div>');
        bindPanel();
    }

    function bindPanel() {
        var panel = PD().getElementById(PANEL_ID);
        if (!panel) return;
        var body = $(panel).find('#ta-panel-body');

        // Tab switching
        body.find('.ta-tab-home').click(function() { currentTab = 'home'; refreshPanel(); });
        body.find('.ta-tab-send').click(function() { currentTab = 'send'; refreshPanel(); });
        body.find('.ta-tab-tts').click(function() { currentTab = 'tts'; refreshPanel(); });
        body.find('.ta-tab-bagu').click(function() { currentTab = 'bagu'; refreshPanel(); });
        body.find('.ta-tab-music').click(function() { currentTab = 'music'; refreshPanel(); });
        body.find('.ta-tab-filter').click(function() { currentTab = 'filter'; refreshPanel(); });
        body.find('.ta-tab-resend').click(function() { currentTab = 'resend'; refreshPanel(); });
        body.find('.ta-tab-regex').click(function() { currentTab = 'regex'; refreshPanel(); });
        body.find('.ta-tab-log').click(function() { currentTab = 'log'; unreadLogAlerts = 0; refreshPanel(); });
        body.find('.ta-status-card[data-tab]').click(function() { currentTab = $(this).attr('data-tab'); if (currentTab === 'log') unreadLogAlerts = 0; refreshPanel(); });

        // Global (all tabs)
        body.find('.ta-log-copy').click(function() {
            var text = logBuf.map(function(e) { return '[' + e.t + '] [' + e.l + '] ' + e.m; }).join('\n');
            window.parent.navigator.clipboard.writeText(text).then(function() { toastr && toastr.success && toastr.success('已复制到剪贴板', 'TTS自动循环'); });
        });
        body.find('.ta-log-clear').click(function() { logBuf = []; unreadLogAlerts = 0; refreshPanel(); });
        body.find('.ta-log-filter').click(function() { logFilter = $(this).attr('data-filter') || 'all'; refreshPanel(); });

        // Home: save/reset
        body.find('.ta-close-btn').click(function() { saveSettings(); closePanel(); });
        body.find('.ta-reset-btn').click(function() {
            if (settings.running || cyclePaused || settings.autoRead || isRangeReading) {
                toastr && toastr.warning && toastr.warning('请先停止当前任务再重置', 'TTS自动循环');
                return;
            }
            if (!window.parent.confirm('确定恢复全部默认设置吗？此操作无法撤销。')) return;
            settings = $.extend(true, {}, DEFAULTS); saveSettings(); refreshPanel();
            toastr && toastr.info && toastr.info('已重置为默认设置', 'TTS自动循环');
        });

        // Home: start/pause/abort + autoRead + range reading + testTTS
        body.find('.ta-mode-card').click(function() {
            if (settings.running || cyclePaused || settings.autoRead || isRangeReading) return;
            homeMode = $(this).attr('data-mode') || 'cycle'; refreshPanel();
        });
        body.find('.ta-ctl-btn').click(function() { startCycle(); });
        body.find('.ta-pause-btn').click(function() { pauseCycle(); });
        body.find('.ta-abort-btn').click(function() { stopCycle(); });
        body.find('.ta-auto-read-start').click(function() { startAutoRead(); });
        body.find('.ta-auto-read-stop').click(function() { stopAutoRead(); });
        body.find('.ta-ar-toggle').change(function() {
            if (this.checked) {
                if (settings.running || cyclePaused) { this.checked = false; toastr && toastr.warning && toastr.warning('请先终止循环', 'TTS自动循环'); return; }
                startAutoRead();
            } else {
                stopAutoRead();
            }
        });
        body.find('.ta-rng-read').click(function() {
            var s = parseInt(body.find('.ta-rng-start').val(), 10) || 1;
            var e = parseInt(body.find('.ta-rng-end').val(), 10) || -1;
            readRange(s, e);
        });
        body.find('.ta-rng-stop').click(function() { stopRangeReading(); });
        body.find('.ta-rng-start, .ta-rng-end').on('input', function() {
            var s = parseInt(body.find('.ta-rng-start').val(), 10) || 1;
            var e = parseInt(body.find('.ta-rng-end').val(), 10) || -1;
            var msgs = getAIMessagesByRange(s, e);
            body.find('.ta-rng-count').text('共 ' + msgs.length + ' 条AI消息');
        });
        body.find('.ta-test-tts-btn').click(function() { testTTS(); });

        // Send tab
        body.find('.ta-as-toggle').change(function() { settings.autoSend.enabled = this.checked; saveSettings(); refreshPanel(); });
        body.find('.ta-as-text').on('input', function() { settings.autoSend.text = this.value.trim() || '继续'; saveSettings(); });
        body.find('.ta-as-mode').change(function() { settings.autoSend.optionMode = this.value; saveSettings(); refreshPanel(); });
        body.find('.ta-as-optidx').on('input', function() { settings.autoSend.optionIndex = Math.max(1, parseInt(this.value, 10) || 1); saveSettings(); });
        body.find('.ta-dream-count').change(function() { settings.autoSend.dreamCountMode = this.value; saveSettings(); });
        body.find('.ta-dream-resolve').change(function() { settings.autoSend.dreamResolveConflicts = this.checked; saveSettings(); });
        body.find('.ta-max-rounds').on('input', function() { settings.autoSend.maxRounds = Math.max(0, parseInt(this.value, 10) || 0); saveSettings(); });
        body.find('.ta-bootstrap-last').change(function() { settings.autoSend.bootstrapLast = this.checked; saveSettings(); });

        // TTS tab
        body.find('.ta-tts-toggle').change(function() { settings.tts.enabled = this.checked; saveSettings(); refreshPanel(); });
        body.find('.ta-tts-voice').change(function() { settings.tts.voice = this.value; saveSettings(); });
        body.find('.ta-tts-rate').on('input', function() { settings.tts.rate = parseInt(this.value, 10); body.find('.ta-rate-val').text(this.value + '%'); saveSettings(); });

        // Bagu tab
        body.find('.ta-bagu-toggle').change(function() {
            settings.bagu.enabled = this.checked;
            if (!this.checked) cancelBaguWork();
            saveSettings(); refreshPanel();
        });
        body.find('.ta-bagu-rewrite').change(function() { settings.bagu.rewriteChat = this.checked; saveSettings(); });
        body.find('.ta-bagu-skip-zero').change(function() { settings.bagu.skipFloorZero = this.checked; saveSettings(); });
        body.find('.ta-bagu-min').on('input', function() { settings.bagu.minLength = Math.max(0, parseInt(this.value, 10) || 0); saveSettings(); });
        body.find('.ta-bagu-timeout').on('input', function() { settings.bagu.timeoutMs = Math.max(10, parseInt(this.value, 10) || 180) * 1000; saveSettings(); });
        body.find('.ta-bagu-api-url').on('input', function() { settings.bagu.apiUrl = this.value.trim(); saveSettings(); updateBaguSourceStatus(); });
        body.find('.ta-bagu-api-key').on('input', function() { settings.bagu.apiKey = this.value.trim(); saveSettings(); });
        body.find('.ta-bagu-key-toggle').click(function() {
            var input = body.find('.ta-bagu-api-key'), showing = input.attr('type') === 'text';
            input.attr('type', showing ? 'password' : 'text'); $(this).text(showing ? '显示' : '隐藏');
        });
        function updateBaguSourceStatus() { body.find('.ta-bagu-source-status').text(baguApiSourceHint(settings.bagu)); }
        body.find('.ta-bagu-model').on('input', function() { settings.bagu.model = this.value.trim(); saveSettings(); updateBaguSourceStatus(); });
        body.find('.ta-bagu-api-source').change(function() { settings.bagu.apiSource = this.value || 'auto'; saveSettings(); updateBaguSourceStatus(); });
        body.find('.ta-bagu-test-api').click(async function() {
            var btn = $(this), status = body.find('.ta-bagu-api-test-status'), old = btn.text();
            btn.prop('disabled', true).text('测试中…'); status.text('正在发送短请求，最多等待60秒…').css('color', '#888');
            try {
                var result = await testBaguApiConnection(settings.bagu);
                status.text('连接成功 · ' + baguApiSourceLabel(result.source) + ' · 返回：' + result.text).css('color', '#4ecdc4');
                btn.text('✓ 成功');
            } catch (e) {
                status.text('测试失败：' + (e.message || e)).css('color', '#f0ad4e'); btn.text('测试失败');
            } finally {
                btn.prop('disabled', false); setTimeout(function() { btn.text(old); }, 2500);
            }
        });
        body.find('.ta-bagu-fetch-models').click(async function() {
            var btn = $(this), select = body.find('.ta-bagu-model-select'), status = body.find('.ta-bagu-model-status');
            var oldText = btn.text();
            btn.prop('disabled', true).text('拉取中…');
            status.text('正在请求模型列表…').css('color', '#888');
            try {
                var apiUrl = body.find('.ta-bagu-api-url').val().trim();
                var apiKey = body.find('.ta-bagu-api-key').val().trim();
                var models = await fetchBaguModels(apiUrl, apiKey);
                var current = body.find('.ta-bagu-model').val().trim();
                var options = '<option value="">— 选择模型 —</option>' + models.map(function(model) {
                    return '<option value="' + escH(model) + '"' + (model === current ? ' selected' : '') + '>' + escH(model) + '</option>';
                }).join('');
                select.html(options).show();
                status.text('已拉取 ' + models.length + ' 个模型 · ' + (models._via === 'tavern' ? '酒馆代拉取' : '浏览器直连')).css('color', '#4ecdc4');
                btn.text('✓ ' + models.length + '个');
            } catch (e) {
                select.hide();
                status.text('拉取失败：' + (e.message || e)).css('color', '#f0ad4e');
                btn.text('拉取失败');
            } finally {
                btn.prop('disabled', false);
                setTimeout(function() { btn.text(oldText); }, 2500);
            }
        });
        body.find('.ta-bagu-model-select').change(function() {
            if (!this.value) return;
            body.find('.ta-bagu-model').val(this.value);
            settings.bagu.model = this.value; saveSettings(); updateBaguSourceStatus();
        });
        body.find('.ta-bagu-extract-start').on('input', function() { settings.bagu.extractStart = this.value; saveSettings(); });
        body.find('.ta-bagu-extract-end').on('input', function() { settings.bagu.extractEnd = this.value; saveSettings(); });
        body.find('.ta-bagu-preview').click(function() { uiPreview.bagu = buildLatestPreview(); refreshPanel(); });
        body.find('.ta-bagu-rerun').click(function() { rerunLatestBagu(); });
        body.find('.ta-filter-preview').click(function() { uiPreview.filter = buildLatestPreview(); refreshPanel(); });
        body.find('.ta-bagu-prompt').on('change', function() { settings.bagu.prompt = this.value.trim() || BAGU_DEFAULT_PROMPT; saveSettings(); });
        body.find('.ta-bagu-reset-prompt').click(function() { settings.bagu.prompt = BAGU_DEFAULT_PROMPT; saveSettings(); refreshPanel(); });
        body.find('.ta-bagu-clear-history').click(function() {
            if (!window.parent.confirm('确定清空全部八股修改记录吗？')) return;
            clearBaguHistory(); refreshPanel();
        });

        // Music tab
        body.find('.ta-bgm-toggle').change(function() {
            settings.bgm.enabled = this.checked; saveSettings();
            if (!bgm) bgm = new BiliBGM();
            if (this.checked) { bgm.ensureHost(); bgm.resume(); } else { bgm.pauseManual(false); bgm.updateVisibility(); }
            refreshPanel();
        });
        body.find('.ta-bili-url').on('input', function() {
            settings.bgm.bilibiliUrl = this.value.trim(); saveSettings();
            if (bgm && bgm.source !== settings.bgm.bilibiliUrl) bgm.setStatus('链接已修改 · 点击从头播放或继续载入');
        });
        body.find('.ta-bili-control').change(function() { settings.bgm.controlMode = this.value; saveSettings(); if (bgm && bgm.active) bgm.load(false); });
        body.find('.ta-bili-show').change(function() { settings.bgm.showPlayer = this.checked; saveSettings(); if (bgm) { bgm.ensureHost(); bgm.updateVisibility(); } });
        body.find('.ta-bili-auto-part').change(function() {
            settings.bgm.autoNextPart = this.checked; saveSettings();
            if (bgm) { if (this.checked) bgm.startPartWatch(); else bgm.clearPartWatch(); }
        });
        body.find('.ta-bili-loop-parts').change(function() { settings.bgm.loopParts = this.checked; saveSettings(); });
        body.find('.ta-bili-continue').change(function() { settings.bgm.continueAfterStop = this.checked; saveSettings(); });
        body.find('.ta-bili-load').click(function() { settings.bgm.bilibiliUrl = body.find('.ta-bili-url').val().trim(); saveSettings(); if (!bgm) bgm = new BiliBGM(); bgm.load(true); });
        body.find('.ta-bili-resume').click(function() { if (!bgm) bgm = new BiliBGM(); bgm.resume(); });
        body.find('.ta-bili-pause').click(function() { if (bgm) bgm.pauseManual(false); });

        // Filter tab
        body.find('.ta-f-toggle').change(function() { settings.textFilter.enabled = this.checked; saveSettings(); refreshPanel(); });
        body.find('.ta-read-on').change(function() { settings.textFilter.readEnabled = this.checked; saveSettings(); });
        body.find('.ta-skip-on').change(function() { settings.textFilter.skipEnabled = this.checked; saveSettings(); });
        body.find('.ta-add-read').click(function() { if (!Array.isArray(settings.textFilter.readRanges)) settings.textFilter.readRanges = []; settings.textFilter.readRanges.push({ start: '', end: '' }); saveSettings(); refreshPanel(); });
        body.find('.ta-add-skip').click(function() { if (!Array.isArray(settings.textFilter.skipRanges)) settings.textFilter.skipRanges = []; settings.textFilter.skipRanges.push({ start: '', end: '' }); saveSettings(); refreshPanel(); });
        body.on('click', '.ta-rm-range', function() { var row = $(this).closest('.ta-range-row'); var idx = parseInt(row.attr('data-idx'), 10); var t = row.attr('data-type'); var arr = t === 'read' ? settings.textFilter.readRanges : settings.textFilter.skipRanges; if (arr) arr.splice(idx, 1); saveSettings(); refreshPanel(); });
        body.on('input', '.ta-range-start, .ta-range-end', function() { var row = $(this).closest('.ta-range-row'); var idx = parseInt(row.attr('data-idx'), 10); var t = row.attr('data-type'); var arr = t === 'read' ? settings.textFilter.readRanges : settings.textFilter.skipRanges; if (arr && arr[idx]) { arr[idx].start = row.find('.ta-range-start').val() || ''; arr[idx].end = row.find('.ta-range-end').val() || ''; saveSettings(); } });

        // Resend tab
        body.find('.ta-rs-toggle').change(function() { settings.textResend.enabled = this.checked; saveSettings(); refreshPanel(); });
        body.find('.ta-add-tag').click(function() { var v = body.find('.ta-rs-tag-input').val().trim(); if (!v) return; if (!Array.isArray(settings.textResend.requiredTags)) settings.textResend.requiredTags = []; if (!settings.textResend.requiredTags.includes(v)) { settings.textResend.requiredTags.push(v); saveSettings(); refreshPanel(); } body.find('.ta-rs-tag-input').val(''); });
        body.on('click', '.ta-tag-rm', function() { var idx = parseInt($(this).attr('data-idx'), 10); if (!isNaN(idx) && Array.isArray(settings.textResend.requiredTags)) { settings.textResend.requiredTags.splice(idx, 1); saveSettings(); refreshPanel(); } });
        body.find('.ta-rs-retries').on('input', function() { settings.textResend.maxRetries = Math.max(1, parseInt(this.value, 10) || 3); saveSettings(); });
        body.find('.ta-rs-delay').on('input', function() { settings.textResend.retryDelay = Math.max(0, parseInt(this.value, 10) || 500); saveSettings(); });

        // Regex tab
        body.find('.ta-rx-toggle').change(function() { settings.regexFilter.enabled = this.checked; saveSettings(); refreshPanel(); });
        body.find('.ta-rx-sync').click(function() { syncRegexes(); refreshPanel(); });
        body.on('change', '.ta-rx-item', function() {
            var id = $(this).attr('data-id');
            var arr = settings.regexFilter.disabledIds || [];
            if (this.checked) { arr = arr.filter(function(x) { return x !== id; }); }
            else { if (arr.indexOf(id) === -1) arr.push(id); }
            settings.regexFilter.disabledIds = arr;
            saveSettings();
        });
    }
    // ============ 键盘 ============
    $(PD()).on('keydown.ta', function(e) { if (e.key === 'Escape' && panelOpen) closePanel(); });

    // ============ 工具 ============
    function dly(ms) { return new Promise(function(r) { setTimeout(r, ms); }); }

    // ============ 初始化 ============
    function initOnce() {
        loadSettings();
        settings.running = false;
        saveSettings();
        injectStyles();
        createOverlay();
        createPanel();
        player = new AudioQ(onPlayerStart, onPlayerFailure, onTTSQueueIdle);
        bgm = new BiliBGM();
        if (settings.bgm.enabled) bgm.ensureHost();
        window.eventOn(window.tavern_events.MESSAGE_RECEIVED, onMsgReceived);
        window.eventOn(window.tavern_events.CHAT_CHANGED, onChatChanged);
        syncRegexes();
        cleanupCache();
        addLog('info', '初始化完毕');
    }

    function register() {
        if (typeof getButtonEvent !== 'function') { setTimeout(register, 1000); return; }
        if (window._ta_registered) return;
        window._ta_registered = true;
        initOnce();
        eventOn(getButtonEvent(BTN_NAME), function() { if (!panelOpen) openPanel(); });
        eventOn(getButtonEvent(BTN_READ), function() {
            if (settings.autoRead) { stopAutoRead(); }
            else if (settings.running) { toastr && toastr.warning && toastr.warning('请先停止循环', 'TTS自动循环'); }
            else { startAutoRead(); }
        });
    }

    register();
})();
